  1→// SPDX-License-Identifier: MIT OR Apache-2.0
  2→//! Codebook backed by graph and vector engines.
  3→//!
  4→//! Each entry is stored as both a graph node (for hierarchy) and a vector
  5→//! embedding in a Poincare-metric collection (for nearest-neighbor search).
  6→
  7→use std::collections::HashMap;
  8→
  9→use graph_engine::{Direction, GraphEngine, PropertyValue};
 10→use vector_engine::{DistanceMetric, SearchResult, VectorCollectionConfig, VectorEngine};
 11→
 12→use crate::error::LearnError;
 13→use crate::poincare::PoincarePoint;
 14→use crate::viz::{VizData, VizEdge, VizMetadata, VizNode};
 15→
 16→/// Collection name used for Poincare embeddings.
 17→const COLLECTION_NAME: &str = "codebook";
 18→
 19→/// A codebook entry mapping a string key to a graph node ID.
 20→#[derive(Debug, Clone)]
 21→struct Entry {
 22→    /// User-provided key.
 23→    key: String,
 24→    /// Graph node ID.
 25→    node_id: u64,
 26→    /// Label for display.
 27→    label: String,
 28→    /// Hierarchy level.
 29→    level: u32,
 30→}
 31→
 32→/// Codebook: a set of entries with graph hierarchy and Poincare embeddings.
 33→pub struct Codebook {
 34→    /// Graph engine for hierarchy relationships.
 35→    graph: GraphEngine,
 36→    /// Vector engine for Poincare nearest-neighbor search.
 37→    vector: VectorEngine,
 38→    /// Dimension of the embedding space.
 39→    dimension: usize,
 40→    /// Curvature parameter.
 41→    curvature: f64,
 42→    /// Entries in insertion order.
 43→    entries: Vec<Entry>,
 44→}
 45→
 46→impl Codebook {
 47→    /// Create a new codebook.
 48→    ///
 49→    /// Configures a `"codebook"` collection with Poincare metric.
 50→    ///
 51→    /// # Errors
 52→    ///
 53→    /// Returns an error if collection creation fails.
 54→    #[allow(clippy::cast_possible_truncation)]
 55→    pub fn new(dimension: usize, curvature: f64) -> Result<Self, LearnError> {
 56→        let graph = GraphEngine::new();
 57→        let vector = VectorEngine::new();
 58→
 59→        let config = VectorCollectionConfig::default()
 60→            .with_dimension(dimension)
 61→            .with_metric(DistanceMetric::Poincare)
 62→            .with_poincare_curvature(curvature as f32);
 63→
 64→        vector.create_collection(COLLECTION_NAME, config)?;
 65→
 66→        Ok(Self {
 67→            graph,
 68→            vector,
 69→            dimension,
 70→            curvature,
 71→            entries: Vec::new(),
 72→        })
 73→    }
 74→
 75→    /// Add an entry to the codebook.
 76→    ///
 77→    /// Creates a graph node with the given label and stores the Poincare
 78→    /// embedding in the codebook collection.
 79→    ///
 80→    /// # Errors
 81→    ///
 82→    /// Returns an error if the point is invalid or storage fails.
 83→    pub fn add_entry(
 84→        &mut self,
 85→        key: &str,
 86→        label: &str,
 87→        point: &PoincarePoint,
 88→        level: u32,
 89→    ) -> Result<(), LearnError> {
 90→        if point.dim() != self.dimension {
 91→            return Err(LearnError::InvalidPoint(format!(
 92→                "expected dimension {}, got {}",
 93→                self.dimension,
 94→                point.dim()
 95→            )));
 96→        }
 97→        if !point.is_valid() {
 98→            return Err(LearnError::InvalidPoint(
 99→                "point lies outside the unit disk".to_string(),
100→            ));
101→        }
102→
103→        // Create graph node with level property
104→        let mut props = HashMap::new();
105→        props.insert("level".to_string(), PropertyValue::Int(i64::from(level)));
106→        props.insert("key".to_string(), PropertyValue::String(key.to_string()));
107→        let node_id = self.graph.create_node(label, props)?;
108→
109→        // Store Poincare embedding
110→        self.vector
111→            .store_in_collection(COLLECTION_NAME, key, point.to_f32_vec())?;
112→
113→        self.entries.push(Entry {
114→            key: key.to_string(),
115→            node_id,
116→            label: label.to_string(),
117→            level,
118→        });
119→        Ok(())
120→    }
121→
122→    /// Add a directed edge between two entries by key.
123→    ///
124→    /// # Errors
125→    ///
126→    /// Returns an error if either entry does not exist.
127→    pub fn add_edge(
128→        &mut self,
129→        from_key: &str,
130→        to_key: &str,
131→        label: &str,
132→    ) -> Result<(), LearnError> {
133→        let from_id = self
134→            .find_node_id(from_key)
135→            .ok_or_else(|| LearnError::Config(format!("entry not found: {from_key}")))?;
136→        let to_id = self
137→            .find_node_id(to_key)
138→            .ok_or_else(|| LearnError::Config(format!("entry not found: {to_key}")))?;
139→
140→        self.graph
141→            .create_edge(from_id, to_id, label, HashMap::new(), true)?;
142→        Ok(())
143→    }
144→
145→    /// Find the k nearest entries to a point.
146→    ///
147→    /// # Errors
148→    ///
149→    /// Returns an error if the search fails.
150→    pub fn nearest(
151→        &self,
152→        point: &PoincarePoint,
153→        k: usize,
154→    ) -> Result<Vec<SearchResult>, LearnError> {
155→        let results = self
156→            .vector
157→            .search_in_collection(COLLECTION_NAME, &point.to_f32_vec(), k)?;
158→        Ok(results)
159→    }
160→
161→    /// Get the children of a node (outgoing edges).
162→    ///
163→    /// # Errors
164→    ///
165→    /// Returns an error if the node does not exist.
166→    pub fn children(&self, key: &str) -> Result<Vec<String>, LearnError> {
167→        let node_id = self
168→            .find_node_id(key)
169→            .ok_or_else(|| LearnError::Config(format!("entry not found: {key}")))?;
170→
171→        let edges = self.graph.edges_of(node_id, Direction::Outgoing)?;
172→        let child_keys: Vec<String> = edges
173→            .iter()
174→            .filter_map(|e| self.find_key_by_node_id(e.to))
175→            .collect();
176→        Ok(child_keys)
177→    }
178→
179→    /// Get the parent of a node (incoming edges).
180→    ///
181→    /// # Errors
182→    ///
183→    /// Returns an error if the node does not exist.
184→    pub fn parent(&self, key: &str) -> Result<Option<String>, LearnError> {
185→        let node_id = self
186→            .find_node_id(key)
187→            .ok_or_else(|| LearnError::Config(format!("entry not found: {key}")))?;
188→
189→        let edges = self.graph.edges_of(node_id, Direction::Incoming)?;
190→        let parent = edges.first().and_then(|e| self.find_key_by_node_id(e.from));
191→        Ok(parent)
192→    }
193→
194→    /// Export codebook state as visualization data.
195→    ///
196→    /// # Errors
197→    ///
198→    /// Returns an error if reading vector state fails.
199→    pub fn to_viz_data(&self) -> Result<VizData, LearnError> {
200→        let mut nodes = Vec::new();
201→        let mut edges = Vec::new();
202→
203→        for entry in &self.entries {
204→            // Get embedding coordinates for visualization
205→            let (x, y) = self
206→                .vector
207→                .get_from_collection(COLLECTION_NAME, &entry.key)
208→                .map_or((0.0, 0.0), |vec| {
209→                    (
210→                        f64::from(*vec.first().unwrap_or(&0.0)),
211→                        f64::from(*vec.get(1).unwrap_or(&0.0)),
212→                    )
213→                });
214→
215→            let distance_from_origin = x.hypot(y);
216→
217→            nodes.push(VizNode {
218→                id: entry.key.clone(),
219→                label: entry.label.clone(),
220→                x,
221→                y,
222→                level: entry.level,
223→                distance_from_origin,
224→            });
225→
226→            // Collect outgoing edges
227→            if let Ok(node_edges) = self.graph.edges_of(entry.node_id, Direction::Outgoing) {
228→                for edge in node_edges {
229→                    if let Some(to_key) = self.find_key_by_node_id(edge.to) {
230→                        edges.push(VizEdge {
231→                            from: entry.key.clone(),
232→                            to: to_key,
233→                            label: edge.edge_type.clone(),
234→                        });
235→                    }
236→                }
237→            }
238→        }
239→
240→        Ok(VizData {
241→            metadata: VizMetadata {
242→                entry_count: nodes.len(),
243→                edge_count: edges.len(),
244→                curvature: self.curvature,
245→                dimension: self.dimension,
246→            },
247→            nodes,
248→            edges,
249→        })
250→    }
251→
252→    /// Number of entries in the codebook.
253→    #[must_use]
254→    pub const fn len(&self) -> usize {
255→        self.entries.len()
256→    }
257→
258→    /// Whether the codebook is empty.
259→    #[must_use]
260→    pub const fn is_empty(&self) -> bool {
261→        self.entries.is_empty()
262→    }
263→
264→    /// Access the graph engine.
265→    #[must_use]
266→    pub const fn graph(&self) -> &GraphEngine {
267→        &self.graph
268→    }
269→
270→    /// Access the vector engine.
271→    #[must_use]
272→    pub const fn vector(&self) -> &VectorEngine {
273→        &self.vector
274→    }
275→
276→    /// Look up a graph node ID by entry key.
277→    fn find_node_id(&self, key: &str) -> Option<u64> {
278→        self.entries
279→            .iter()
280→            .find(|e| e.key == key)
281→            .map(|e| e.node_id)
282→    }
283→
284→    /// Look up an entry key by graph node ID.
285→    fn find_key_by_node_id(&self, node_id: u64) -> Option<String> {
286→        self.entries
287→            .iter()
288→            .find(|e| e.node_id == node_id)
289→            .map(|e| e.key.clone())
290→    }
291→}
