 92→/// Return current visualization data as JSON.
 93→pub async fn viz_data(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
 94→    let Some(ref training) = ctx.training else {
 95→        return (
 96→            StatusCode::NOT_FOUND,
 97→            Json(serde_json::json!({"error": "no training session"})),
 98→        )
 99→            .into_response();
100→    };
101→
102→    let session = training.read();
103→    match session.to_viz_data() {
104→        Ok(data) => Json(data).into_response(),
105→        Err(e) => (
106→            StatusCode::INTERNAL_SERVER_ERROR,
107→            Json(serde_json::json!({"error": e.to_string()})),
108→        )
109→            .into_response(),
110→    }
111→}
112→
113→/// Return current training status as JSON.
114→pub async fn status(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
115→    let Some(ref training) = ctx.training else {
116→        return (
117→            StatusCode::NOT_FOUND,
118→            Json(serde_json::json!({"error": "no training session"})),
119→        )
120→            .into_response();
121→    };
122→
123→    let session = training.read();
124→    Json(session.stats()).into_response()
125→}
126→
127→/// Start or resume training.
128→pub async fn start(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
129→    let Some(ref training) = ctx.training else {
130→        return StatusCode::NOT_FOUND;
131→    };
132→
133→    let mut session = training.write();
134→    session.start();
135→    StatusCode::OK
136→}
137→
138→/// Toggle pause.
139→pub async fn pause(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
140→    let Some(ref training) = ctx.training else {
141→        return StatusCode::NOT_FOUND;
142→    };
143→
144→    let mut session = training.write();
145→    if session.status() == tensor_learn::TrainingStatus::Paused {
146→        session.resume();
147→    } else {
148→        session.pause();
149→    }
150→    StatusCode::OK
151→}
152→
153→/// Execute a single training step.
154→pub async fn step(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
155→    let Some(ref training) = ctx.training else {
156→        return (
157→            StatusCode::NOT_FOUND,
158→            Json(serde_json::json!({"error": "no training session"})),
159→        )
160→            .into_response();
161→    };
162→
163→    let mut session = training.write();
164→    match session.step() {
165→        Ok(()) => Json(session.stats()).into_response(),
166→        Err(e) => (
167→            StatusCode::INTERNAL_SERVER_ERROR,
168→            Json(serde_json::json!({"error": e.to_string()})),
169→        )
170→            .into_response(),
171→    }
172→}
173→
174→/// Embedded JavaScript for the Poincare disk renderer and controls.
175→const LEARN_SCRIPT: &str = r"<script>
176→(function() {
177→    const canvas = document.getElementById('poincare-canvas');
178→    const dCtx = canvas.getContext('2d');
179→    let vizData = null;
180→    let pollTimer = null;
181→
182→    function draw() {
183→        const w = canvas.width, h = canvas.height;
184→        const cx = w / 2, cy = h / 2;
185→        const r = Math.min(cx, cy) - 20;
186→
187→        dCtx.clearRect(0, 0, w, h);
188→
189→        // Unit circle
190→        dCtx.beginPath();
191→        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
192→        dCtx.strokeStyle = '#444';
193→        dCtx.lineWidth = 2;
194→        dCtx.stroke();
195→
196→        // Radial grid
197→        for (let i = 1; i <= 4; i++) {
198→            dCtx.beginPath();
199→            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
200→            dCtx.strokeStyle = '#2a2a2a';
201→            dCtx.lineWidth = 0.5;
202→            dCtx.stroke();
203→        }
204→
205→        if (!vizData) return;
206→
207→        // Draw edges as lines (geodesic arcs approximated as straight lines)
208→        const nodeMap = {};
209→        for (const n of vizData.nodes) {
210→            nodeMap[n.id] = n;
211→        }
212→        for (const edge of vizData.edges) {
213→            const from = nodeMap[edge.from];
214→            const to = nodeMap[edge.to];
215→            if (!from || !to) continue;
216→            const x1 = cx + from.x * r, y1 = cy - from.y * r;
217→            const x2 = cx + to.x * r, y2 = cy - to.y * r;
218→            dCtx.beginPath();
219→            dCtx.moveTo(x1, y1);
220→            dCtx.lineTo(x2, y2);
221→            dCtx.strokeStyle = '#555';
222→            dCtx.lineWidth = 1;
223→            dCtx.stroke();
224→        }
225→
226→        // Draw nodes colored by level
227→        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
228→        for (const n of vizData.nodes) {
229→            const x = cx + n.x * r;
230→            const y = cy - n.y * r;
231→            const col = colors[n.level % colors.length];
232→            const sz = 8 - n.level;
233→
234→            dCtx.beginPath();
235→            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
236→            dCtx.fillStyle = col;
237→            dCtx.fill();
238→            dCtx.strokeStyle = '#fff';
239→            dCtx.lineWidth = 1;
240→            dCtx.stroke();
241→
242→            // Label
243→            dCtx.font = '11px Inter, sans-serif';
244→            dCtx.fillStyle = '#ccc';
245→            dCtx.textAlign = 'center';
246→            dCtx.fillText(n.label, x, y - sz - 4);
247→        }
248→    }
249→
250→    async function fetchViz() {
251→        try {
252→            const resp = await fetch('/learn/viz');
253→            if (resp.ok) {
254→                vizData = await resp.json();
255→                draw();
256→            }
257→        } catch (_) {}
258→    }
259→
260→    async function trainAction(action) {
261→        try {
262→            const method = action === 'step' ? 'POST' : 'POST';
263→            await fetch('/learn/' + action, { method });
264→            await fetchViz();
265→            // Refresh stats
266→            const sr = await fetch('/learn/status');
267→            if (sr.ok) {
268→                const st = await sr.json();
269→                updateStats(st);
270→                managePoll(st.status);
271→            }
272→        } catch (_) {}
273→    }
274→
275→    function updateStats(st) {
276→        // Simple DOM update approach
277→        const cards = document.querySelectorAll('.m-card .text-lg');
278→        if (cards.length >= 4) {
279→            const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
280→            cards[0].textContent = statusName[st.status] || st.status;
281→            cards[1].textContent = st.step + ' / ' + st.total_steps;
282→            cards[2].textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
283→            cards[3].textContent = st.entry_count;
284→        }
285→    }
286→
287→    function managePoll(status) {
288→        if (status === 'Running') {
289→            if (!pollTimer) {
290→                pollTimer = setInterval(async () => {
291→                    await fetchViz();
292→                    const sr = await fetch('/learn/status');
293→                    if (sr.ok) {
294→                        const st = await sr.json();
295→                        updateStats(st);
296→                        if (st.status !== 'Running') {
297→                            clearInterval(pollTimer);
298→                            pollTimer = null;
299→                        }
300→                    }
301→                }, 500);
302→            }
303→        } else {
304→            if (pollTimer) {
305→                clearInterval(pollTimer);
306→                pollTimer = null;
307→            }
308→        }
309→    }
310→
311→    // Make trainAction available globally
312→    window.trainAction = trainAction;
313→
314→    // Initial fetch
315→    fetchViz();
316→})();
317→</script>";
318→

