        // Controls
        div class="flex gap-3 mb-6" {
            button id="btn-start" class="m-btn" onclick="trainAction('start')" { "Start" }
            button id="btn-pause" class="m-btn" onclick="trainAction('pause')" { "Pause" }
            button id="btn-step" class="m-btn" onclick="trainAction('step')" { "Step" }
        }

        // Poincare disk visualization
        div class="m-card" style="position: relative;" {
            canvas id="poincare-canvas" width="600" height="600"
                style="display: block; margin: 0 auto; background: var(--bg-secondary); border-radius: 8px;" {}
        }

        // Embedded JS for the Poincare disk renderer and auto-refresh
        (PreEscaped(LEARN_SCRIPT))
    };

    layout("Learn", NavItem::Learn, content)
}

/// Return current visualization data as JSON.
pub async fn viz_data(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    match session.to_viz_data() {
        Ok(data) => Json(data).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Return current training status as JSON.
pub async fn status(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    Json(session.stats()).into_response()
}

/// Start or resume training.
pub async fn start(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    session.start();
    StatusCode::OK
}

/// Toggle pause.
pub async fn pause(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    if session.status() == tensor_learn::TrainingStatus::Paused {
        session.resume();
    } else {
        session.pause();
    }
    StatusCode::OK
}

/// Execute a single training step.
pub async fn step(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let mut session = training.write();
    match session.step() {
        Ok(()) => Json(session.stats()).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Embedded JavaScript for the Poincare disk renderer and controls.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const canvas = document.getElementById('poincare-canvas');
    const dCtx = canvas.getContext('2d');
    let vizData = null;
    let pollTimer = null;

    function draw() {
        const w = canvas.width, h = canvas.height;
        const cx = w / 2, cy = h / 2;
        const r = Math.min(cx, cy) - 20;

        dCtx.clearRect(0, 0, w, h);

        // Unit circle
        dCtx.beginPath();
        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
        dCtx.strokeStyle = '#444';
        dCtx.lineWidth = 2;
        dCtx.stroke();

        // Radial grid
        for (let i = 1; i <= 4; i++) {
            dCtx.beginPath();
            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
            dCtx.strokeStyle = '#2a2a2a';
            dCtx.lineWidth = 0.5;
            dCtx.stroke();
        }

        if (!vizData) return;

        // Draw edges as lines (geodesic arcs approximated as straight lines)
        const nodeMap = {};
        for (const n of vizData.nodes) {
            nodeMap[n.id] = n;
        }
        for (const edge of vizData.edges) {
            const from = nodeMap[edge.from];
            const to = nodeMap[edge.to];
            if (!from || !to) continue;
            const x1 = cx + from.x * r, y1 = cy - from.y * r;
            const x2 = cx + to.x * r, y2 = cy - to.y * r;
            dCtx.beginPath();
            dCtx.moveTo(x1, y1);
            dCtx.lineTo(x2, y2);
            dCtx.strokeStyle = '#555';
            dCtx.lineWidth = 1;
            dCtx.stroke();
        }

        // Draw nodes colored by level
        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
        for (const n of vizData.nodes) {
            const x = cx + n.x * r;
            const y = cy - n.y * r;
            const col = colors[n.level % colors.length];
            const sz = 8 - n.level;

            dCtx.beginPath();
            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
            dCtx.fillStyle = col;
            dCtx.fill();
            dCtx.strokeStyle = '#fff';
            dCtx.lineWidth = 1;
            dCtx.stroke();

            // Label
            dCtx.font = '11px Inter, sans-serif';
            dCtx.fillStyle = '#ccc';
            dCtx.textAlign = 'center';
            dCtx.fillText(n.label, x, y - sz - 4);
        }
    }

    async function fetchViz() {
        try {
            const resp = await fetch('/learn/viz');
            if (resp.ok) {
                vizData = await resp.json();
                draw();
            }
        } catch (_) {}
    }

    async function trainAction(action) {
        try {
            const method = action === 'step' ? 'POST' : 'POST';
            await fetch('/learn/' + action, { method });
            await fetchViz();
            // Refresh stats
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateStats(st);
                managePoll(st.status);
            }
        } catch (_) {}
    }

    function updateStats(st) {
        // Simple DOM update approach
        const cards = document.querySelectorAll('.m-card .text-lg');
        if (cards.length >= 4) {
            const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
            cards[0].textContent = statusName[st.status] || st.status;
            cards[1].textContent = st.step + ' / ' + st.total_steps;
            cards[2].textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
            cards[3].textContent = st.entry_count;
        }
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateStats(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer);
                            pollTimer = null;
                        }
                    }
                }, 500);
            }
        } else {
            if (pollTimer) {
                clearInterval(pollTimer);
                pollTimer = null;
            }
        }
    }

    // Make trainAction available globally
    window.trainAction = trainAction;

    // Initial fetch
    fetchViz();
})();
</script>";

