// SPDX-License-Identifier: MIT OR Apache-2.0
//! Training session for the geometric intelligence model.
//!
//! Manages iterative training with step-by-step progress tracking
//! and visualization export.

use serde::{Deserialize, Serialize};

use crate::codebook::Codebook;
use crate::error::LearnError;
use crate::viz::VizData;

/// Training status.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum TrainingStatus {
    /// Training has not started.
    Idle,
    /// Training is actively running.
    Running,
    /// Training is paused.
    Paused,
    /// Training has completed.
    Completed,
}

/// Training statistics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrainingStats {
    /// Current training step.
    pub step: usize,
    /// Total number of steps to run.
    pub total_steps: usize,
    /// Current status.
    pub status: TrainingStatus,
    /// Loss at the current step (lower is better).
    pub loss: f64,
    /// Best loss seen so far.
    pub best_loss: f64,
    /// Number of entries in the codebook.
    pub entry_count: usize,
}

/// Configuration for a training session.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrainingConfig {
    /// Total number of training steps.
    pub total_steps: usize,
    /// Learning rate for gradient updates.
    pub learning_rate: f64,
    /// Curvature of the Poincare disk.
    pub curvature: f64,
    /// Dimension of the embedding space.
    pub dimension: usize,
}

impl Default for TrainingConfig {
    fn default() -> Self {
        Self {
            total_steps: 100,
            learning_rate: 0.01,
            curvature: 1.0,
            dimension: 2,
        }
    }
}

/// A training session managing codebook learning.
pub struct TrainingSession {
    /// The codebook being trained.
    codebook: Codebook,
    /// Training configuration.
    config: TrainingConfig,
    /// Current step.
    step: usize,
    /// Current status.
    status: TrainingStatus,
    /// Current loss.
    loss: f64,
    /// Best loss seen.
    best_loss: f64,
}

impl TrainingSession {
    /// Create a new training session with the given codebook and config.
    #[must_use]
    pub const fn new(codebook: Codebook, config: TrainingConfig) -> Self {
        Self {
            codebook,
            config,
            step: 0,
            status: TrainingStatus::Idle,
            loss: f64::MAX,
            best_loss: f64::MAX,
        }
    }

    /// Start the training session.
    pub const fn start(&mut self) {
        self.status = TrainingStatus::Running;
    }

    /// Pause the training session.
    pub fn pause(&mut self) {
        if self.status == TrainingStatus::Running {
            self.status = TrainingStatus::Paused;
        }
    }

    /// Resume a paused session.
    pub fn resume(&mut self) {
        if self.status == TrainingStatus::Paused {
            self.status = TrainingStatus::Running;
        }
    }

    /// Execute a single training step.
    ///
    /// Computes pairwise distances between codebook entries and
    /// updates loss based on hierarchy-distance consistency.
    ///
    /// # Errors
    ///
    /// Returns an error if reading codebook state fails.
    pub fn step(&mut self) -> Result<(), LearnError> {
        if self.status != TrainingStatus::Running {
            self.start();
        }

        // Compute loss: sum of distance-from-origin weighted by level
        // Higher-level nodes should be closer to the origin
        let viz = self.codebook.to_viz_data()?;
        let mut total_loss = 0.0;

        for node in &viz.nodes {
            let expected_dist = f64::from(node.level) * 0.3;
            let actual_dist = node.distance_from_origin;
            let diff = actual_dist - expected_dist;
            total_loss += diff * diff;
        }

        if !viz.nodes.is_empty() {
            #[allow(clippy::cast_precision_loss)]
            let count = viz.nodes.len() as f64;
            total_loss /= count;
        }

        self.loss = total_loss;
        if total_loss < self.best_loss {
            self.best_loss = total_loss;
        }

        self.step += 1;
        if self.step >= self.config.total_steps {
            self.status = TrainingStatus::Completed;
        }

        Ok(())
    }

    /// Get current training statistics.
    #[must_use]
    pub const fn stats(&self) -> TrainingStats {
        TrainingStats {
            step: self.step,
            total_steps: self.config.total_steps,
            status: self.status,
            loss: self.loss,
            best_loss: self.best_loss,
            entry_count: self.codebook.len(),
        }
    }

    /// Get current status.
    #[must_use]
    pub const fn status(&self) -> TrainingStatus {
        self.status
    }

    /// Export current state as visualization data.
    ///
    /// # Errors
    ///
    /// Returns an error if reading codebook state fails.
    pub fn to_viz_data(&self) -> Result<VizData, LearnError> {
        self.codebook.to_viz_data()
    }

    /// Access the codebook.
    #[must_use]
    pub const fn codebook(&self) -> &Codebook {
        &self.codebook
    }

    /// Mutable access to the codebook.
    pub const fn codebook_mut(&mut self) -> &mut Codebook {
        &mut self.codebook
    }

    /// Access the training config.
    #[must_use]
    pub const fn config(&self) -> &TrainingConfig {
        &self.config
    }
}

