// SPDX-License-Identifier: MIT OR Apache-2.0
//! Geometric learning dashboard handlers.
//!
//! Renders a Poincare disk visualization with training controls
//! and statistics. All JS/CSS is embedded as Rust string constants.

use std::sync::Arc;

use axum::extract::State;
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use maud::{html, Markup, PreEscaped};

use crate::web::templates::{layout, m_empty, m_header};
use crate::web::{AdminContext, NavItem};

/// Main learning dashboard page.
pub async fn dashboard(State(ctx): State<Arc<AdminContext>>) -> Markup {
    let Some(ref training) = ctx.training else {
        return layout(
            "Learn",
            NavItem::Learn,
            m_empty(
                "Training Not Configured",
                "Start the server with a training session to use the learning dashboard.",
            ),
        );
    };

    let stats = training.read().stats();

    let content = html! {
        (m_header("Geometric Learning", Some("Poincare disk codebook training")))

        div class="grid grid-cols-1 lg:grid-cols-4 gap-4 mb-6" {
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Status" }
                div class="text-lg font-mono text-[var(--text-primary)]" {
                    @match stats.status {
                        tensor_learn::TrainingStatus::Idle => "IDLE",
                        tensor_learn::TrainingStatus::Running => "RUNNING",
                        tensor_learn::TrainingStatus::Paused => "PAUSED",
                        tensor_learn::TrainingStatus::Completed => "COMPLETED",
                    }
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Step" }
                div class="text-lg font-mono text-[var(--text-primary)]" {
                    (format!("{} / {}", stats.step, stats.total_steps))
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Loss" }
                div class="text-lg font-mono text-[var(--text-primary)]" {
                    @if stats.loss < f64::MAX {
                        (format!("{:.6}", stats.loss))
                    } @else {
                        "-"
                    }
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Entries" }
                div class="text-lg font-mono text-[var(--text-primary)]" {
                    (stats.entry_count)
                }
            }
        }

        // Controls
        div class="flex gap-3 mb-6" {
            button id="btn-start" class="m-btn" onclick="trainAction('start')" { "Start" }
            button id="btn-pause" class="m-btn" onclick="trainAction('pause')" { "Pause" }
            button id="btn-step" class="m-btn" onclick="trainAction('step')" { "Step" }
        }

        // Poincare disk visualization
        div class="m-card" style="position: relative;" {
            canvas id="poincare-canvas" width="600" height="600"
                style="display: block; margin: 0 auto; background: var(--bg-secondary); border-radius: 8px;" {}
        }

        // Embedded JS for the Poincare disk renderer and auto-refresh
        (PreEscaped(LEARN_SCRIPT))
    };

    layout("Learn", NavItem::Learn, content)
}

/// Return current visualization data as JSON.
pub async fn viz_data(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    match session.to_viz_data() {
        Ok(data) => Json(data).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Return current training status as JSON.
pub async fn status(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    Json(session.stats()).into_response()
}

/// Start or resume training.
pub async fn start(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    session.start();
    StatusCode::OK
}

/// Toggle pause.
pub async fn pause(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    if session.status() == tensor_learn::TrainingStatus::Paused {
        session.resume();
    } else {
        session.pause();
    }
    StatusCode::OK
}

/// Execute a single training step.
pub async fn step(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let mut session = training.write();
    match session.step() {
        Ok(()) => Json(session.stats()).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Embedded JavaScript for the Poincare disk renderer and controls.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const canvas = document.getElementById('poincare-canvas');
    const dCtx = canvas.getContext('2d');
    let vizData = null;
    let pollTimer = null;

    function draw() {
        const w = canvas.width, h = canvas.height;
        const cx = w / 2, cy = h / 2;
        const r = Math.min(cx, cy) - 20;

        dCtx.clearRect(0, 0, w, h);

        // Unit circle
        dCtx.beginPath();
        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
        dCtx.strokeStyle = '#444';
        dCtx.lineWidth = 2;
        dCtx.stroke();

        // Radial grid
        for (let i = 1; i <= 4; i++) {
            dCtx.beginPath();
            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
            dCtx.strokeStyle = '#2a2a2a';
            dCtx.lineWidth = 0.5;
            dCtx.stroke();
        }

        if (!vizData) return;

        // Draw edges as lines (geodesic arcs approximated as straight lines)
        const nodeMap = {};
        for (const n of vizData.nodes) {
            nodeMap[n.id] = n;
        }
        for (const edge of vizData.edges) {
            const from = nodeMap[edge.from];
            const to = nodeMap[edge.to];
            if (!from || !to) continue;
            const x1 = cx + from.x * r, y1 = cy - from.y * r;
            const x2 = cx + to.x * r, y2 = cy - to.y * r;
            dCtx.beginPath();
            dCtx.moveTo(x1, y1);
            dCtx.lineTo(x2, y2);
            dCtx.strokeStyle = '#555';
            dCtx.lineWidth = 1;
            dCtx.stroke();
        }

        // Draw nodes colored by level
        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
        for (const n of vizData.nodes) {
            const x = cx + n.x * r;
            const y = cy - n.y * r;
            const col = colors[n.level % colors.length];
            const sz = 8 - n.level;

            dCtx.beginPath();
            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
            dCtx.fillStyle = col;
            dCtx.fill();
            dCtx.strokeStyle = '#fff';
            dCtx.lineWidth = 1;
            dCtx.stroke();

            // Label
            dCtx.font = '11px Inter, sans-serif';
            dCtx.fillStyle = '#ccc';
            dCtx.textAlign = 'center';
            dCtx.fillText(n.label, x, y - sz - 4);
        }
    }

    async function fetchViz() {
        try {
            const resp = await fetch('/learn/viz');
            if (resp.ok) {
                vizData = await resp.json();
                draw();
            }
        } catch (_) {}
    }

    async function trainAction(action) {
        try {
            const method = action === 'step' ? 'POST' : 'POST';
            await fetch('/learn/' + action, { method });
            await fetchViz();
            // Refresh stats
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateStats(st);
                managePoll(st.status);
            }
        } catch (_) {}
    }

    function updateStats(st) {
        // Simple DOM update approach
        const cards = document.querySelectorAll('.m-card .text-lg');
        if (cards.length >= 4) {
            const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
            cards[0].textContent = statusName[st.status] || st.status;
            cards[1].textContent = st.step + ' / ' + st.total_steps;
            cards[2].textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
            cards[3].textContent = st.entry_count;
        }
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateStats(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer);
                            pollTimer = null;
                        }
                    }
                }, 500);
            }
        } else {
            if (pollTimer) {
                clearInterval(pollTimer);
                pollTimer = null;
            }
        }
    }

    // Make trainAction available globally
    window.trainAction = trainAction;

    // Initial fetch
    fetchViz();
})();
</script>";

// SPDX-License-Identifier: MIT OR Apache-2.0
//! Synthetic hierarchy tasks for evaluating hyperbolic learning.
//!
//! Provides [`HierarchyTask`] which generates structured graphs (e.g.
//! binary trees) and converts them into ready-to-train sessions.

use std::collections::HashSet;

use rand::seq::SliceRandom;
use rand::{Rng, SeedableRng};

use crate::codebook::Codebook;
use crate::error::LearnError;
use crate::poincare::PoincarePoint;
use crate::training::{TrainingConfig, TrainingSession};

/// A synthetic hierarchy with known structure for training evaluation.
///
/// Stores node keys, hierarchy levels, and directed edges as index pairs.
pub struct HierarchyTask {
    /// Node keys in BFS order.
    keys: Vec<String>,
    /// Hierarchy level for each node (root = 0).
    levels: Vec<u32>,
    /// Directed edges as `(parent_idx, child_idx)`.
    edges: Vec<(usize, usize)>,
}

impl HierarchyTask {
    /// Create a complete binary tree of the given depth.
    ///
    /// Depth 0 produces a single root node. Depth 3 produces 15 nodes
    /// across 4 levels. Nodes are named `"n0"`, `"n1"`, ... in BFS order.
    #[must_use]
    pub fn binary_tree(depth: u32) -> Self {
        let node_count = (1_usize << (depth + 1)) - 1;
        let mut keys = Vec::with_capacity(node_count);
        let mut levels = Vec::with_capacity(node_count);
        let mut edges = Vec::with_capacity(node_count.saturating_sub(1));

        for i in 0..node_count {
            keys.push(format!("n{i}"));
            levels.push(Self::level_of(i));
            if i > 0 {
                edges.push(((i - 1) / 2, i));
            }
        }

        Self {
            keys,
            levels,
            edges,
        }
    }

    /// Number of nodes in the task.
    #[must_use]
    pub fn node_count(&self) -> usize {
        self.keys.len()
    }

    /// Edge pairs as `(parent_key, child_key)` references.
    #[must_use]
    pub fn edge_pairs(&self) -> Vec<(&str, &str)> {
        self.edges
            .iter()
            .map(|&(p, c)| (self.keys[p].as_str(), self.keys[c].as_str()))
            .collect()
    }

    /// Entries as `(key, level)` references.
    #[must_use]
    pub fn entries(&self) -> Vec<(&str, u32)> {
        self.keys
            .iter()
            .zip(self.levels.iter())
            .map(|(k, &l)| (k.as_str(), l))
            .collect()
    }

    /// Sample non-edge pairs for negative training.
    ///
    /// Precomputes the full pool of unordered non-edge pairs, then samples
    /// `min(count, pool.len())` without replacement. Returns fewer than
    /// `count` when the pool is smaller (depth-0 returns empty).
    pub fn negative_samples<R: Rng>(&self, count: usize, rng: &mut R) -> Vec<(usize, usize)> {
        let edge_set: HashSet<(usize, usize)> = self
            .edges
            .iter()
            .copied()
            .flat_map(|(a, b)| [(a, b), (b, a)])
            .collect();

        let n = self.keys.len();
        let mut pool: Vec<(usize, usize)> = Vec::new();
        for i in 0..n {
            for j in (i + 1)..n {
                if !edge_set.contains(&(i, j)) {
                    pool.push((i, j));
                }
            }
        }

        let sample_count = count.min(pool.len());
        if sample_count == 0 {
            return Vec::new();
        }

        let (shuffled, _) = pool.partial_shuffle(rng, sample_count);
        shuffled.to_vec()
    }

    /// Convert this task into a ready-to-train session.
    ///
    /// Creates a [`Codebook`] with random initial embeddings (uniform in
    /// `[-0.1, 0.1]` per dimension) and all hierarchy edges. The RNG is
    /// seeded from `config.seed`.
    ///
    /// # Errors
    ///
    /// Returns an error if `config.dimension != 2` (Phase 2 constraint)
    /// or if codebook creation fails.
    pub fn into_session(self, config: TrainingConfig) -> Result<TrainingSession, LearnError> {
        if config.dimension != 2 {
            return Err(LearnError::Config(
                "dimension must be 2 for Phase 2 training".to_string(),
            ));
        }

        let mut codebook = Codebook::new(config.dimension, config.curvature)?;
        let mut rng = rand::rngs::StdRng::seed_from_u64(config.seed);

        for (i, key) in self.keys.iter().enumerate() {
            let coords: Vec<f64> = (0..config.dimension)
                .map(|_| rng.random_range(-0.1..0.1))
                .collect();
            let point = PoincarePoint::new(coords);
            codebook.add_entry(key, key, &point, self.levels[i])?;
        }

        for &(parent_idx, child_idx) in &self.edges {
            codebook.add_edge(&self.keys[parent_idx], &self.keys[child_idx], "child")?;
        }

        Ok(TrainingSession::new(codebook, config))
    }

    /// Compute BFS level from zero-based index.
    fn level_of(index: usize) -> u32 {
        usize::BITS - (index + 1).leading_zeros() - 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn binary_tree_depth_0() {
        let task = HierarchyTask::binary_tree(0);
        assert_eq!(task.node_count(), 1);
        assert!(task.edges.is_empty());
        assert_eq!(task.keys[0], "n0");
    }

    #[test]
    fn binary_tree_depth_3() {
        let task = HierarchyTask::binary_tree(3);
        assert_eq!(task.node_count(), 15);
        assert_eq!(task.edges.len(), 14);
    }

    #[test]
    fn binary_tree_levels() {
        let task = HierarchyTask::binary_tree(3);
        assert_eq!(task.levels[0], 0); // root
        assert_eq!(task.levels[1], 1);
        assert_eq!(task.levels[2], 1);
        assert_eq!(task.levels[3], 2);
        assert_eq!(task.levels[6], 2);
        assert_eq!(task.levels[7], 3);
        assert_eq!(task.levels[14], 3);
    }

    #[test]
    fn negative_samples_excludes_edges() {
        let task = HierarchyTask::binary_tree(2);
        let mut rng = rand::rngs::StdRng::seed_from_u64(0);
        let edge_set: HashSet<(usize, usize)> = task
            .edges
            .iter()
            .copied()
            .flat_map(|(a, b)| [(a, b), (b, a)])
            .collect();
        let samples = task.negative_samples(100, &mut rng);
        for (a, b) in &samples {
            assert!(
                !edge_set.contains(&(*a, *b)),
                "negative sample ({a}, {b}) is an edge"
            );
        }
    }

    #[test]
    fn negative_samples_bounded_by_pool() {
        let task = HierarchyTask::binary_tree(1);
        // 3 nodes, 2 edges -> pool = C(3,2) - 2 = 1 pair
        let mut rng = rand::rngs::StdRng::seed_from_u64(0);
        let samples = task.negative_samples(1000, &mut rng);
        assert!(samples.len() <= 1, "pool has at most 1 non-edge pair");
    }

    #[test]
    fn into_session_creates_valid_session() {
        let task = HierarchyTask::binary_tree(3);
        let config = TrainingConfig {
            total_steps: 10,
            dimension: 2,
            ..TrainingConfig::default()
        };
        let session = task.into_session(config).unwrap();
        assert_eq!(session.codebook().len(), 15);
    }

    #[test]
    fn into_session_random_init_inside_disk() {
        let task = HierarchyTask::binary_tree(3);
        let config = TrainingConfig {
            total_steps: 10,
            dimension: 2,
            ..TrainingConfig::default()
        };
        let session = task.into_session(config).unwrap();
        let viz = session.to_viz_data().unwrap();
        for node in &viz.nodes {
            let r = node.x.hypot(node.y);
            assert!(
                r < 1.0,
                "node {} at ({}, {}) outside disk",
                node.id,
                node.x,
                node.y
            );
        }
    }

    #[test]
    fn into_session_rejects_non_2d() {
        let task = HierarchyTask::binary_tree(2);
        let config = TrainingConfig {
            dimension: 3,
            ..TrainingConfig::default()
        };
        let result = task.into_session(config);
        assert!(result.is_err());
    }
}

