11→async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
12→    // Initialize tracing
13→    tracing_subscriber::fmt()
14→        .with_env_filter(
15→            tracing_subscriber::EnvFilter::from_default_env()
