17→                .add_directive("query_router=info".parse()?)
18→                .add_directive("tower_http=debug".parse()?),
19→        )
20→        .init();
21→
22→    // Load configuration from environment or defaults
23→    let config = ServerConfig::from_env()?;
24→
25→    tracing::info!("Starting Neumann server on {}", config.bind_addr);
26→
27→    // Create the query router
28→    let router = Arc::new(RwLock::new(QueryRouter::new()));
29→
30→    // Initialize cluster mode if configured
31→    if let Some(ref cluster_config) = config.cluster {
32→        router.write().init_cluster_with_wal(
33→            &cluster_config.node_id,
34→            cluster_config.raft_bind_addr,
35→            &cluster_config.peers,
36→            &cluster_config.data_dir,
