174→/// Embedded JavaScript for the Poincare disk renderer and controls.
175→const LEARN_SCRIPT: &str = r"<script>
176→(function() {
177→    const canvas = document.getElementById('poincare-canvas');
178→    const dCtx = canvas.getContext('2d');
179→    let vizData = null;
180→    let pollTimer = null;
181→
182→    function draw() {
183→        const w = canvas.width, h = canvas.height;
184→        const cx = w / 2, cy = h / 2;
185→        const r = Math.min(cx, cy) - 20;
186→
187→        dCtx.clearRect(0, 0, w, h);
188→
189→        // Unit circle
190→        dCtx.beginPath();
191→        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
192→        dCtx.strokeStyle = '#444';
193→        dCtx.lineWidth = 2;
194→        dCtx.stroke();
195→
196→        // Radial grid
197→        for (let i = 1; i <= 4; i++) {
198→            dCtx.beginPath();
199→            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
200→            dCtx.strokeStyle = '#2a2a2a';
201→            dCtx.lineWidth = 0.5;
202→            dCtx.stroke();
203→        }
204→
205→        if (!vizData) return;
206→
207→        // Draw edges as lines (geodesic arcs approximated as straight lines)
208→        const nodeMap = {};
209→        for (const n of vizData.nodes) {
210→            nodeMap[n.id] = n;
211→        }
212→        for (const edge of vizData.edges) {
213→            const from = nodeMap[edge.from];
214→            const to = nodeMap[edge.to];
215→            if (!from || !to) continue;
216→            const x1 = cx + from.x * r, y1 = cy - from.y * r;
217→            const x2 = cx + to.x * r, y2 = cy - to.y * r;
218→            dCtx.beginPath();
219→            dCtx.moveTo(x1, y1);
220→            dCtx.lineTo(x2, y2);
221→            dCtx.strokeStyle = '#555';
222→            dCtx.lineWidth = 1;
223→            dCtx.stroke();
224→        }
225→
226→        // Draw nodes colored by level
227→        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
228→        for (const n of vizData.nodes) {
229→            const x = cx + n.x * r;
230→            const y = cy - n.y * r;
231→            const col = colors[n.level % colors.length];
232→            const sz = 8 - n.level;
233→
234→            dCtx.beginPath();
235→            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
236→            dCtx.fillStyle = col;
237→            dCtx.fill();
238→            dCtx.strokeStyle = '#fff';
239→            dCtx.lineWidth = 1;
240→            dCtx.stroke();
241→
242→            // Label
243→            dCtx.font = '11px Inter, sans-serif';
244→            dCtx.fillStyle = '#ccc';
245→            dCtx.textAlign = 'center';
246→            dCtx.fillText(n.label, x, y - sz - 4);
247→        }
248→    }
249→
250→    async function fetchViz() {
251→        try {
252→            const resp = await fetch('/learn/viz');
253→            if (resp.ok) {
254→                vizData = await resp.json();
255→                draw();
256→            }
257→        } catch (_) {}
258→    }
259→
260→    async function trainAction(action) {
261→        try {
262→            const method = action === 'step' ? 'POST' : 'POST';
263→            await fetch('/learn/' + action, { method });
264→            await fetchViz();
265→            // Refresh stats
266→            const sr = await fetch('/learn/status');
267→            if (sr.ok) {
268→                const st = await sr.json();
269→                updateStats(st);
270→                managePoll(st.status);
271→            }
272→        } catch (_) {}
273→    }
274→
275→    function updateStats(st) {
276→        // Simple DOM update approach
277→        const cards = document.querySelectorAll('.m-card .text-lg');
278→        if (cards.length >= 4) {
279→            const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
280→            cards[0].textContent = statusName[st.status] || st.status;
281→            cards[1].textContent = st.step + ' / ' + st.total_steps;
282→            cards[2].textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
283→            cards[3].textContent = st.entry_count;
284→        }
285→    }
286→
287→    function managePoll(status) {
288→        if (status === 'Running') {
289→            if (!pollTimer) {
290→                pollTimer = setInterval(async () => {
291→                    await fetch('/learn/step', { method: 'POST' });
292→                    await fetchViz();
293→                    const sr = await fetch('/learn/status');
294→                    if (sr.ok) {
295→                        const st = await sr.json();
296→                        updateStats(st);
297→                        if (st.status !== 'Running') {
298→                            clearInterval(pollTimer);
299→                            pollTimer = null;
300→                        }
301→                    }
302→                }, 500);
303→            }
304→        } else {
305→            if (pollTimer) {
306→                clearInterval(pollTimer);
307→                pollTimer = null;
308→            }
309→        }
310→    }
311→
312→    // Make trainAction available globally
313→    window.trainAction = trainAction;
314→
315→    // Initial fetch
316→    fetchViz();
317→})();
318→</script>";
