 72→/// Environment variable parsing helpers.
 73→mod env_parse {
 74→    use std::net::SocketAddr;
 75→    use std::path::PathBuf;
 76→    use std::time::Duration;
 77→
 78→    use super::{Result, ServerError};
 79→
 80→    /// Parse a socket address from an environment variable.
 81→    pub fn parse_socket_addr(key: &str) -> Option<Result<SocketAddr>> {
 82→        std::env::var(key).ok().map(|val| {
 83→            val.parse()
 84→                .map_err(|e| ServerError::Config(format!("invalid {key}: {e}")))
 85→        })
 86→    }
 87→
 88→    /// Parse a usize from an environment variable.
 89→    pub fn parse_usize(key: &str) -> Option<Result<usize>> {
 90→        std::env::var(key).ok().map(|val| {
 91→            val.parse()
 92→                .map_err(|e| ServerError::Config(format!("invalid {key}: {e}")))
 93→        })
 94→    }
 95→
 96→    /// Parse a u32 from an environment variable.
 97→    pub fn parse_u32(key: &str) -> Option<Result<u32>> {
 98→        std::env::var(key).ok().map(|val| {
 99→            val.parse()
100→                .map_err(|e| ServerError::Config(format!("invalid {key}: {e}")))
101→        })
102→    }
103→
104→    /// Parse a boolean from an environment variable.
105→    /// Accepts "true", "1", "yes", "on" as true (case-insensitive).
106→    /// Accepts "false", "0", "no", "off" as false (case-insensitive).
107→    pub fn parse_bool(key: &str) -> Option<Result<bool>> {
108→        std::env::var(key)
109→            .ok()
110→            .map(|val| match val.to_lowercase().as_str() {
111→                "true" | "1" | "yes" | "on" => Ok(true),
112→                "false" | "0" | "no" | "off" => Ok(false),
113→                _ => Err(ServerError::Config(format!(
114→                    "invalid {key}: expected boolean (true/false/1/0/yes/no/on/off)"
115→                ))),
116→            })
117→    }
118→
119→    /// Parse a duration in seconds from an environment variable.
120→    pub fn parse_duration_secs(key: &str) -> Option<Result<Duration>> {
121→        std::env::var(key).ok().map(|val| {
122→            val.parse::<u64>()
123→                .map(Duration::from_secs)
124→                .map_err(|e| ServerError::Config(format!("invalid {key}: {e}")))
125→        })
126→    }
127→
128→    /// Parse a path from an environment variable.
129→    pub fn parse_path(key: &str) -> Option<PathBuf> {
130→        std::env::var(key).ok().map(PathBuf::from)
131→    }
132→}
