 816→        });
 817→
 818→        // Add services and start gRPC server
 819→        if self.config.enable_grpc_web {
 820→            let layer = GrpcWebLayer::new();
 821→            let mut router = builder
 822→                .layer(layer)
 823→                .add_service(query_svc)
 824→                .add_service(health_svc);
 825→
 826→            if let Some(blob) = blob_svc {
 827→                router = router.add_service(blob);
 828→            }
 829→            if let Some(points) = points_svc {
 830→                router = router.add_service(points);
 831→            }
 832→            if let Some(collections) = collections_svc {
 833→                router = router.add_service(collections);
 834→            }
 835→            if let Some(refl) = reflection_svc {
 836→                router = router.add_service(refl);
 837→            }
 838→
 839→            // Run gRPC server with optional REST and Web servers
 840→            match (rest_task, web_task) {
 841→                (Some(rest), Some(web)) => {
 842→                    tokio::select! {
 843→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 844→                        result = rest => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("REST task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 845→                        result = web => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("Web task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 846→                    }
 847→                },
 848→                (Some(rest), None) => {
 849→                    tokio::select! {
 850→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 851→                        result = rest => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("REST task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 852→                    }
 853→                },
 854→                (None, Some(web)) => {
 855→                    tokio::select! {
 856→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 857→                        result = web => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("Web task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 858→                    }
 859→                },
 860→                (None, None) => {
 861→                    router.serve_with_shutdown(addr, drain_future).await?;
 862→                },
 863→            }
 864→        } else {
 865→            let mut router = builder.add_service(query_svc).add_service(health_svc);
 866→
 867→            if let Some(blob) = blob_svc {
 868→                router = router.add_service(blob);
 869→            }
 870→            if let Some(points) = points_svc {
 871→                router = router.add_service(points);
 872→            }
 873→            if let Some(collections) = collections_svc {
 874→                router = router.add_service(collections);
 875→            }
 876→            if let Some(refl) = reflection_svc {
 877→                router = router.add_service(refl);
 878→            }
 879→
 880→            // Run gRPC server with optional REST and Web servers
 881→            match (rest_task, web_task) {
 882→                (Some(rest), Some(web)) => {
 883→                    tokio::select! {
 884→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 885→                        result = rest => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("REST task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 886→                        result = web => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("Web task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 887→                    }
 888→                },
 889→                (Some(rest), None) => {
 890→                    tokio::select! {
 891→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 892→                        result = rest => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("REST task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 893→                    }
 894→                },
 895→                (None, Some(web)) => {
 896→                    tokio::select! {
 897→                        result = router.serve_with_shutdown(addr, drain_future) => result?,
 898→                        result = web => result.map_err(|e: tokio::task::JoinError| ServerError::Internal(format!("Web task panic: {e}")))?.map_err(|e| ServerError::Internal(e.to_string()))?,
 899→                    }
 900→                },
 901→                (None, None) => {
 902→                    router.serve_with_shutdown(addr, drain_future).await?;
 903→                },
 904→            }
 905→        }
 906→
 907→        Ok(())
 908→    }
 909→}
