268→    /// Load TLS configuration from files.
269→    fn load_tls_config(tls: &TlsConfig) -> Result<ServerTlsConfig> {
270→        let cert = std::fs::read(&tls.cert_path).map_err(|e| {
271→            ServerError::Config(format!(
272→                "failed to read certificate file {}: {e}",
273→                tls.cert_path.display()
274→            ))
275→        })?;
276→        let key = std::fs::read(&tls.key_path).map_err(|e| {
277→            ServerError::Config(format!(
278→                "failed to read key file {}: {e}",
279→                tls.key_path.display()
280→            ))
281→        })?;
282→
283→        let identity = Identity::from_pem(&cert, &key);
284→
285→        let mut tls_config = ServerTlsConfig::new().identity(identity);
286→
287→        if let Some(ref ca_path) = tls.ca_cert_path {
288→            let ca_cert = std::fs::read(ca_path).map_err(|e| {
289→                ServerError::Config(format!(
290→                    "failed to read CA certificate file {}: {e}",
291→                    ca_path.display()
292→                ))
293→            })?;
294→            let ca = tonic::transport::Certificate::from_pem(ca_cert);
295→            tls_config = tls_config.client_ca_root(ca);
296→
297→            // When CA is set but require_client_cert is false, make client auth optional.
298→            // When require_client_cert is true (or not set), client cert is required (default).
299→            if !tls.require_client_cert {
300→                tls_config = tls_config.client_auth_optional(true);
301→            }
302→        }
303→
304→        Ok(tls_config)
305→    }
