307→    /// Start the gRPC server.
308→    ///
309→    /// This method blocks until the server is shut down.
310→    ///
311→    /// # Errors
312→    ///
313→    /// Returns an error if the server fails to start or encounters a runtime error.
314→    #[allow(clippy::too_many_lines)]
315→    pub async fn serve(self) -> Result<()> {
316→        self.config.validate()?;
317→
318→        let addr = self.config.bind_addr;
319→        let tls_enabled = self.config.tls.is_some();
320→
321→        if tls_enabled {
322→            tracing::info!("Starting Neumann gRPC server with TLS on {}", addr);
323→        } else {
324→            tracing::info!("Starting Neumann gRPC server on {}", addr);
325→        }
326→
327→        // Create shared health state
328→        let health_state = Arc::new(HealthState::new());
329→
330→        // Create services with configuration, health monitoring, rate limiting, audit, and metrics
331→        let query_service = QueryServiceImpl::with_full_config(
332→            Arc::clone(&self.router),
333→            self.config.auth.clone(),
334→            self.config.stream_channel_capacity,
335→            Arc::clone(&health_state),
336→            self.rate_limiter.clone(),
337→            self.audit_logger.clone(),
338→            self.metrics.clone(),
339→        );
340→
341→        let health_service = HealthServiceImpl::with_state(Arc::clone(&health_state));
342→
343→        // Build services router
344→        let query_svc = QueryServiceServer::new(query_service);
345→        let health_svc = HealthServer::new(health_service);
346→
347→        // Load TLS configuration if enabled
348→        let tls_config = if let Some(ref tls) = self.config.tls {
349→            Some(Self::load_tls_config(tls)?)
350→        } else {
351→            None
352→        };
353→
354→        // Build server with optional TLS
355→        let mut builder = if let Some(tls_cfg) = tls_config {
356→            Server::builder().tls_config(tls_cfg)?
357→        } else {
358→            Server::builder()
359→        };
360→
361→        // Apply HTTP/2 settings
362→        if let Some(max_streams) = self.config.max_concurrent_streams_per_connection {
363→            builder = builder.http2_max_pending_accept_reset_streams(Some(max_streams as usize));
364→        }
365→        if let Some(window_size) = self.config.initial_window_size {
366→            builder = builder.initial_stream_window_size(window_size);
367→        }
368→        if let Some(conn_window) = self.config.initial_connection_window_size {
369→            builder = builder.initial_connection_window_size(conn_window);
370→        }
371→        if let Some(limit) = self.config.max_concurrent_connections {
372→            builder = builder.concurrency_limit_per_connection(limit);
373→        }
374→        if let Some(timeout) = self.config.request_timeout {
375→            builder = builder.timeout(timeout);
376→        }
377→
378→        // Apply gRPC-web layer if enabled
379→        if self.config.enable_grpc_web {
380→            // Note: gRPC-web requires HTTP/1 support
381→            builder = builder.accept_http1(true);
382→        }
383→
384→        // Build reflection service if enabled
385→        let reflection_svc = if self.config.enable_reflection {
386→            tracing::info!("Reflection service enabled");
387→            Some(
388→                tonic_reflection::server::Builder::configure()
389→                    .register_encoded_file_descriptor_set(proto::FILE_DESCRIPTOR_SET)
390→                    .build_v1()
391→                    .map_err(|e| {
392→                        ServerError::Internal(format!("Failed to build reflection service: {e}"))
393→                    })?,
394→            )
395→        } else {
396→            None
397→        };
398→
399→        // Build blob service if store is available

400→        let blob_svc = self.blob_store.as_ref().map(|store| {
401→            let blob_service = BlobServiceImpl::with_full_config(
402→                Arc::clone(store),
403→                &self.config,
404→                self.rate_limiter.clone(),
405→                self.audit_logger.clone(),
406→                self.metrics.clone(),
407→            );
408→            tracing::info!("Blob service enabled");
409→            BlobServiceServer::new(blob_service)
410→        });
411→
412→        // Build vector services if engine is available
413→        let (points_svc, collections_svc) = if let Some(ref engine) = self.vector_engine {
414→            let points_service = PointsServiceImpl::with_full_config(
415→                Arc::clone(engine),
416→                self.config.auth.clone(),
417→                Some(Arc::clone(&health_state)),
418→                self.rate_limiter.clone(),
419→                self.audit_logger.clone(),
420→                self.metrics.clone(),
421→            );
422→            let collections_service = CollectionsServiceImpl::with_full_config(
423→                Arc::clone(engine),
424→                self.config.auth.clone(),
425→                self.rate_limiter.clone(),
426→                self.audit_logger.clone(),
427→                self.metrics.clone(),
428→            );
429→            tracing::info!("Vector services enabled");
430→            (
431→                Some(PointsServiceServer::new(points_service)),
432→                Some(CollectionsServiceServer::new(collections_service)),
433→            )
434→        } else {
435→            (None, None)
436→        };
437→
438→        // Build REST server if configured
439→        let rest_handle = if let (Some(rest_addr), Some(ref engine)) =
440→            (self.config.rest_addr, &self.vector_engine)
441→        {
442→            let rest_ctx = Arc::new(
443→                VectorApiContext::new(Arc::clone(engine))
444→                    .with_auth(self.config.auth.clone())
445→                    .with_rate_limiter(self.rate_limiter.clone())
446→                    .with_audit_logger(self.audit_logger.clone())
447→                    .with_metrics(self.metrics.clone())
448→                    .with_spatial(Some(self.router.read().spatial().clone()))
449→                    .with_spatial_3d(self.spatial_3d.clone()),
450→            );
451→            let rest_router = rest::router_with_config(rest_ctx, &self.config.rest_config);
452→            let listener = TcpListener::bind(rest_addr).await.map_err(|e| {
453→                ServerError::Internal(format!("failed to bind REST server to {rest_addr}: {e}"))
454→            })?;
455→            tracing::info!("REST API enabled on {}", rest_addr);
456→            Some(tokio::spawn(async move {
457→                axum::serve(listener, rest_router)
458→                    .await
459→                    .map_err(|e| ServerError::Internal(format!("REST server error: {e}")))
460→            }))
461→        } else {
462→            None
463→        };
464→
465→        // Build Web admin server if configured and all engines are available
466→        let web_handle =
467→            if let (Some(web_addr), Some(ref relational), Some(ref vector), Some(ref graph)) = (
468→                self.config.web_addr,
469→                &self.relational_engine,
470→                &self.vector_engine,
471→                &self.graph_engine,
472→            ) {
473→                let web_ctx = Arc::new(
474→                    web::AdminContext::new(
475→                        Arc::clone(relational),
476→                        Arc::clone(vector),
477→                        Arc::clone(graph),
478→                    )
479→                    .with_unified(self.unified_engine.clone())
480→                    .with_vault(self.vault_engine.clone())
481→                    .with_cache(self.cache_engine.clone())
482→                    .with_blob(self.blob_store.clone())
483→                    .with_auth(self.config.auth.clone())
484→                    .with_metrics(self.metrics.clone())
485→                    .with_query_router(Some(Arc::clone(&self.router))),
486→                );
487→                let web_router = web::router(web_ctx);
488→                let listener = TcpListener::bind(web_addr).await.map_err(|e| {
489→                    ServerError::Internal(format!("failed to bind Web server to {web_addr}: {e}"))
490→                })?;
