pub mod web;

/// Generated protobuf types.
#[allow(missing_docs)]
#[allow(clippy::all, clippy::pedantic, clippy::nursery)]
pub mod proto {
    tonic::include_proto!("neumann.v1");

    /// Vector service protobuf types.
    pub mod vector {
        tonic::include_proto!("neumann.vector.v1");
    }

