        let tls = TlsConfig {
            cert_path,
            key_path: std::path::PathBuf::from("/nonexistent/key.pem"),
            ca_cert_path: None,
            require_client_cert: false,
        };

        let result = NeumannServer::load_tls_config(&tls);
