        let server = NeumannServer::new(router, config).with_spatial_3d(Arc::clone(&spatial));

        assert!(server.spatial_3d.is_some());
        assert!(Arc::ptr_eq(server.spatial_3d.as_ref().unwrap(), &spatial));
    }
}

