        )
            .into_response(),
    }
}

/// Parameters for resetting the training session.
#[derive(Deserialize)]
pub struct ResetParams {
    /// Total steps for the new session.
    total_steps: Option<usize>,
    /// Learning rate for the new session.
    learning_rate: Option<f64>,
    /// RNG seed for the new session.
    seed: Option<u64>,
}

/// Reset training with a fresh binary-tree session.
pub async fn reset(
    State(ctx): State<Arc<AdminContext>>,
    Json(params): Json<ResetParams>,
) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let task = tensor_learn::HierarchyTask::binary_tree(3);
    let config = tensor_learn::TrainingConfig {
        total_steps: params.total_steps.unwrap_or(200),
        learning_rate: params.learning_rate.unwrap_or(0.1),
        seed: params.seed.unwrap_or(42),
        dimension: 2,
        curvature: 1.0,
        ..tensor_learn::TrainingConfig::default()
    };

    match task.into_session(config) {
        Ok(session) => {
            *training.write() = session;
            StatusCode::OK.into_response()
        },
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

