/// Main learning dashboard page.
pub async fn dashboard(State(ctx): State<Arc<AdminContext>>) -> Markup {
    let Some(ref training) = ctx.training else {
        return layout(
            "Learn",
            NavItem::Learn,
            m_empty(
                "Training Not Configured",
                "Start the server with NEUMANN_LEARN=1 to enable the learning dashboard.",
            ),
        );
    };

    let stats = training.read().stats();

    let content = html! {
        (m_header("Geometric Learning", Some("Poincare disk codebook training")))

        // Stats cards
        div class="grid grid-cols-1 lg:grid-cols-4 gap-4 mb-6" {
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Status" }
                div id="stat-status" class="text-lg font-mono text-[var(--text-primary)]" {
                    @match stats.status {
                        tensor_learn::TrainingStatus::Idle => "IDLE",
                        tensor_learn::TrainingStatus::Running => "RUNNING",
                        tensor_learn::TrainingStatus::Paused => "PAUSED",
                        tensor_learn::TrainingStatus::Completed => "COMPLETED",
                    }
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Step" }
                div id="stat-step" class="text-lg font-mono text-[var(--text-primary)]" {
                    (format!("{} / {}", stats.step, stats.total_steps))
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Loss" }
                div id="stat-loss" class="text-lg font-mono text-[var(--text-primary)]" {
                    @if stats.loss < f64::MAX { (format!("{:.6}", stats.loss)) } @else { "-" }
                }
            }
            div class="m-card" {
                div class="text-xs text-[var(--text-tertiary)] uppercase tracking-wide mb-1" { "Best Loss" }
                div id="stat-best" class="text-lg font-mono text-[var(--text-primary)]" {
                    @if stats.best_loss < f64::MAX { (format!("{:.6}", stats.best_loss)) } @else { "-" }
                }
            }
        }

        // Controls row
        div class="flex flex-wrap gap-3 mb-6 items-end" {
            button class="m-btn" onclick="trainAction('start')" { "Start" }
            button class="m-btn" onclick="trainAction('pause')" { "Pause" }
