/// Embedded JavaScript for the research dashboard.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const diskCanvas = document.getElementById('poincare-canvas');
    const diskCtx   = diskCanvas.getContext('2d');
    const chartCanvas = document.getElementById('loss-chart');
    const chartCtx  = chartCanvas.getContext('2d');
    const logEl     = document.getElementById('log-output');
    let vizData = null, pollTimer = null, lastStep = -1;

    const el = id => document.getElementById(id);
    const pad = (n, w) => String(n).padStart(w);
    const f = (v, d) => v.toFixed(d);

    function log(msg) { logEl.textContent += msg + '\n'; logEl.scrollTop = logEl.scrollHeight; }

    // -- Poincare disk renderer --
    function drawDisk() {
        const w = diskCanvas.width, h = diskCanvas.height;
        const cx = w/2, cy = h/2, r = Math.min(cx,cy) - 16;
        diskCtx.clearRect(0, 0, w, h);

        // Boundary
        diskCtx.beginPath(); diskCtx.arc(cx, cy, r, 0, 2*Math.PI);
        diskCtx.strokeStyle = '#333'; diskCtx.lineWidth = 1.5; diskCtx.stroke();

        // Radial rings at hyperbolic distances
        for (let i = 1; i <= 4; i++) {
            diskCtx.beginPath(); diskCtx.arc(cx, cy, r*i/5, 0, 2*Math.PI);
            diskCtx.strokeStyle = '#1a1a1a'; diskCtx.lineWidth = 0.5; diskCtx.stroke();
        }

        if (!vizData || !vizData.nodes.length) return;
        const nm = {}; for (const n of vizData.nodes) nm[n.id] = n;

        // Edges
        diskCtx.strokeStyle = '#333'; diskCtx.lineWidth = 0.8;
        for (const e of vizData.edges) {
            const a = nm[e.from], b = nm[e.to]; if (!a||!b) continue;
            diskCtx.beginPath();
            diskCtx.moveTo(cx + a.x*r, cy - a.y*r);
            diskCtx.lineTo(cx + b.x*r, cy - b.y*r);
            diskCtx.stroke();
        }

        // Nodes by level
        const pal = ['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#ec4899'];
        for (const n of vizData.nodes) {
            const x = cx + n.x*r, y = cy - n.y*r;
            const col = pal[n.level % pal.length];
            const sz = Math.max(7 - n.level, 3);
            diskCtx.beginPath(); diskCtx.arc(x, y, sz, 0, 2*Math.PI);
            diskCtx.fillStyle = col; diskCtx.fill();
            diskCtx.strokeStyle = '#000'; diskCtx.lineWidth = 0.5; diskCtx.stroke();
            diskCtx.font = '10px monospace'; diskCtx.fillStyle = '#888';
            diskCtx.textAlign = 'center'; diskCtx.fillText(n.label, x, y - sz - 3);
        }
    }

    // -- Loss chart renderer --
    function drawChart(history) {
        const w = chartCanvas.width, h = chartCanvas.height;
        const P = {l:48, r:8, t:12, b:22};
        const pw = w-P.l-P.r, ph = h-P.t-P.b;
        chartCtx.clearRect(0, 0, w, h);

        if (!history || history.length < 2) {
            chartCtx.fillStyle = '#444'; chartCtx.font = '12px monospace';
            chartCtx.textAlign = 'center'; chartCtx.fillText('Awaiting data...', w/2, h/2);
            return;
        }

        const mn = Math.min(...history), mx = Math.max(...history);
        const rng = mx - mn || 1;
        const toX = i => P.l + (i/(history.length-1))*pw;
        const toY = v => P.t + ((mx-v)/rng)*ph;

        // Grid
        chartCtx.strokeStyle = '#222'; chartCtx.lineWidth = 0.5;
        for (let i = 0; i <= 4; i++) {
            const y = P.t + ph*i/4;
            chartCtx.beginPath(); chartCtx.moveTo(P.l, y); chartCtx.lineTo(w-P.r, y); chartCtx.stroke();
        }

        // Loss line
        chartCtx.beginPath(); chartCtx.strokeStyle = '#3b82f6'; chartCtx.lineWidth = 1.5;
        for (let i = 0; i < history.length; i++) {
            const x = toX(i), y = toY(history[i]);
            i === 0 ? chartCtx.moveTo(x,y) : chartCtx.lineTo(x,y);
        }
        chartCtx.stroke();

        // Moving average (window 20)
        if (history.length > 20) {
            chartCtx.beginPath(); chartCtx.strokeStyle = '#f59e0b'; chartCtx.lineWidth = 1.5;
            const wn = 20;
            let sum = 0;
            for (let i = 0; i < history.length; i++) {
                sum += history[i];
                if (i >= wn) sum -= history[i - wn];
                if (i >= wn - 1) {
                    const avg = sum / wn;
                    const x = toX(i), y = toY(avg);
                    i === wn - 1 ? chartCtx.moveTo(x,y) : chartCtx.lineTo(x,y);
                }
            }
            chartCtx.stroke();
        }

        // Axis labels
        chartCtx.fillStyle = '#555'; chartCtx.font = '9px monospace'; chartCtx.textAlign = 'right';
        chartCtx.fillText(f(mx,3), P.l-4, P.t+8);
        chartCtx.fillText(f(mn,3), P.l-4, P.t+ph+3);
        chartCtx.textAlign = 'center';
        chartCtx.fillText('step', w/2, h-3);
        chartCtx.textAlign = 'left';
        chartCtx.fillText(history.length.toString(), toX(history.length-1)-10, h-3);

        // Legend
        chartCtx.fillStyle = '#3b82f6'; chartCtx.fillRect(P.l+4, P.t+2, 12, 3);
        chartCtx.fillStyle = '#666'; chartCtx.font = '9px monospace'; chartCtx.textAlign = 'left';
        chartCtx.fillText('loss', P.l+20, P.t+8);
        if (history.length > 20) {
            chartCtx.fillStyle = '#f59e0b'; chartCtx.fillRect(P.l+54, P.t+2, 12, 3);
            chartCtx.fillStyle = '#666'; chartCtx.fillText('ma20', P.l+70, P.t+8);
        }
    }

    // -- Metrics computed from viz data --
    function metrics() {
        if (!vizData || !vizData.nodes.length) return null;
        const nm = {}; for (const n of vizData.nodes) nm[n.id] = n;
        let correct = 0, total = 0;
        for (const e of vizData.edges) {
            const p = nm[e.from], c = nm[e.to]; if (!p||!c) continue;
            total++; if (p.distance_from_origin < c.distance_from_origin) correct++;
        }
        const root = vizData.nodes.find(n => n.level === 0);
        const maxLevel = Math.max(...vizData.nodes.map(n => n.level));
        const leaves = vizData.nodes.filter(n => n.level === maxLevel);
        const leafAvg = leaves.length ? leaves.reduce((s,n) => s + n.distance_from_origin, 0)/leaves.length : 0;
        return {
            acc: total ? correct/total : 0,
            rootDist: root ? root.distance_from_origin : 0,
            leafAvg, total, correct,
        };
    }

    // -- Fetching --
    async function fetchViz() {
        try {
            const r = await fetch('/learn/viz');
            if (r.ok) { vizData = await r.json(); drawDisk(); }
        } catch(_) {}
    }

    // -- UI updates --
    function updateUI(st) {
        const sn = {Idle:'IDLE',Running:'RUNNING',Paused:'PAUSED',Completed:'DONE'};
        el('stat-status').textContent = sn[st.status] || st.status;
        el('stat-step').textContent = st.step + ' / ' + st.total_steps;
        el('stat-loss').textContent = st.loss < 1e300 ? f(st.loss,4) : '-';
        el('stat-best').textContent = st.best_loss < 1e300 ? f(st.best_loss,4) : '-';
        const m = metrics();
        if (m) {
            el('stat-acc').textContent = Math.round(m.acc*100) + '%';
            el('stat-root').textContent = f(m.rootDist, 3);
        }
        drawChart(st.loss_history);
    }

    function logStep(st) {
        if (st.step <= lastStep) return;
        lastStep = st.step;
        const m = metrics();
        let s = pad(st.step,5) + '/' + pad(st.total_steps,-1);
        s += '  loss=' + f(st.loss,4);
        s += '  E=' + f(st.edge_loss,4);
        s += '  R=' + f(st.radial_loss,4);
        s += '  N=' + f(st.negative_loss,4);
        if (m) s += '  acc=' + pad(Math.round(m.acc*100),3) + '%  root=' + f(m.rootDist,3) + '  leaf=' + f(m.leafAvg,3);
        log(s);
    }

    // -- Actions --
    async function trainAction(action) {
        try {
            // Auto-reset if starting a completed session
            if (action === 'start') {
                const sr = await fetch('/learn/status');
                if (sr.ok) {
                    const st = await sr.json();
                    if (st.status === 'Completed') { await doReset(); }
                }
            }
            await fetch('/learn/' + action, { method: 'POST' });
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateUI(st);
                managePoll(st.status);
            }
        } catch(_) {}
    }

    async function singleStep() {
        try {
            const r = await fetch('/learn/step', { method: 'POST' });
            await fetchViz();
            if (r.ok) { const st = await r.json(); updateUI(st); logStep(st); }
        } catch(_) {}
    }

    function getParams() {
        return {
            total_steps: parseInt(el('in-steps').value) || 1000,
            learning_rate: parseFloat(el('in-lr').value) || 0.1,
            seed: parseInt(el('in-seed').value) || 42,
            depth: parseInt(el('in-depth').value) || 3,
        };
    }

    async function doReset() {
        const p = getParams();
        await fetch('/learn/reset', {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify(p),
        });
        lastStep = -1;
    }

    async function resetSession() {
        const p = getParams();
        logEl.textContent = '';
        log('--- Reset: steps=' + p.total_steps + ' lr=' + p.learning_rate + ' depth=' + p.depth + ' seed=' + p.seed + ' ---');
        await doReset();
        await fetchViz();
        const sr = await fetch('/learn/status');
        if (sr.ok) updateUI(await sr.json());
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetch('/learn/step', { method: 'POST' });
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateUI(st);
                        logStep(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer); pollTimer = null;
                            const m = metrics();
                            log('--- Done. best=' + f(st.best_loss,4) + (m ? ' acc=' + Math.round(m.acc*100) + '%' : '') + ' ---');
                        }
                    }
                }, 200);
            }
        } else {
            if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
        }
    }

    window.trainAction = trainAction;
    window.singleStep = singleStep;
    window.resetSession = resetSession;
    fetchViz();
    drawChart(null);
})();
</script>";

