/// Embedded JavaScript for the Poincare disk renderer, log, and controls.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const canvas = document.getElementById('poincare-canvas');
    const dCtx = canvas.getContext('2d');
    const logEl = document.getElementById('log-output');
    let vizData = null;
    let pollTimer = null;
    let lastLoggedStep = -1;

    function log(msg) {
        logEl.textContent += msg + '\n';
        logEl.scrollTop = logEl.scrollHeight;
    }

    function draw() {
        const w = canvas.width, h = canvas.height;
        const cx = w / 2, cy = h / 2;
        const r = Math.min(cx, cy) - 20;

        dCtx.clearRect(0, 0, w, h);

        // Unit circle
        dCtx.beginPath();
        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
        dCtx.strokeStyle = '#444';
        dCtx.lineWidth = 2;
        dCtx.stroke();

        // Radial grid + labels
        for (let i = 1; i <= 4; i++) {
            dCtx.beginPath();
            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
            dCtx.strokeStyle = '#2a2a2a';
            dCtx.lineWidth = 0.5;
            dCtx.stroke();
        }

        if (!vizData) return;

        const nodeMap = {};
        for (const n of vizData.nodes) nodeMap[n.id] = n;

        // Edges
        for (const edge of vizData.edges) {
            const from = nodeMap[edge.from], to = nodeMap[edge.to];
            if (!from || !to) continue;
            dCtx.beginPath();
            dCtx.moveTo(cx + from.x * r, cy - from.y * r);
            dCtx.lineTo(cx + to.x * r, cy - to.y * r);
            dCtx.strokeStyle = '#555';
            dCtx.lineWidth = 1;
            dCtx.stroke();
        }

        // Nodes
        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
        for (const n of vizData.nodes) {
            const x = cx + n.x * r, y = cy - n.y * r;
            const col = colors[n.level % colors.length];
            const sz = 8 - n.level;
            dCtx.beginPath();
            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
            dCtx.fillStyle = col;
            dCtx.fill();
            dCtx.strokeStyle = '#fff';
            dCtx.lineWidth = 1;
            dCtx.stroke();
            dCtx.font = '11px Inter, sans-serif';
            dCtx.fillStyle = '#ccc';
            dCtx.textAlign = 'center';
            dCtx.fillText(n.label, x, y - sz - 4);
        }
    }

    function vizStats() {
        if (!vizData || !vizData.nodes.length) return null;
        const root = vizData.nodes.find(n => n.level === 0);
        const leaves = vizData.nodes.filter(n => n.level === 3);
        const leafAvg = leaves.length ? leaves.reduce((s,n) => s + n.distance_from_origin, 0) / leaves.length : 0;
        const leafMax = leaves.length ? Math.max(...leaves.map(n => n.distance_from_origin)) : 0;
        return {
            rootDist: root ? root.distance_from_origin : 0,
            leafAvg: leafAvg,
            leafMax: leafMax,
        };
    }

    async function fetchViz() {
        try {
            const resp = await fetch('/learn/viz');
            if (resp.ok) { vizData = await resp.json(); draw(); }
        } catch (_) {}
    }

    function updateStatsUI(st) {
        const el = id => document.getElementById(id);
        const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
        el('stat-status').textContent = statusName[st.status] || st.status;
        el('stat-step').textContent = st.step + ' / ' + st.total_steps;
        el('stat-loss').textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
        el('stat-best').textContent = st.best_loss < 1e300 ? st.best_loss.toFixed(6) : '-';
    }

    function logStep(st) {
        if (st.step <= lastLoggedStep) return;
        lastLoggedStep = st.step;
        const vs = vizStats();
        let line = 'Step ' + String(st.step).padStart(4) + '/' + st.total_steps;
        line += '  loss=' + st.loss.toFixed(4);
        line += '  edge=' + st.edge_loss.toFixed(4);
        line += '  radial=' + st.radial_loss.toFixed(4);
        line += '  neg=' + st.negative_loss.toFixed(4);
        if (vs) {
            line += '  root_d=' + vs.rootDist.toFixed(3);
            line += '  leaf_avg=' + vs.leafAvg.toFixed(3);
        }
        log(line);
    }

    async function trainAction(action) {
        try {
            await fetch('/learn/' + action, { method: 'POST' });
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateStatsUI(st);
                if (action === 'step') logStep(st);
                managePoll(st.status);
            }
        } catch (_) {}
    }

    async function resetSession() {
        const steps = parseInt(document.getElementById('in-steps').value) || 200;
        const lr = parseFloat(document.getElementById('in-lr').value) || 0.1;
        const seed = parseInt(document.getElementById('in-seed').value) || 42;
        try {
            await fetch('/learn/reset', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({total_steps: steps, learning_rate: lr, seed: seed})
            });
            logEl.textContent = '';
            lastLoggedStep = -1;
            log('--- Reset: steps=' + steps + ' lr=' + lr + ' seed=' + seed + ' ---');
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) updateStatsUI(await sr.json());
        } catch(e) { log('Reset error: ' + e); }
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetch('/learn/step', { method: 'POST' });
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateStatsUI(st);
                        logStep(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer);
                            pollTimer = null;
                            log('--- Training completed. Best loss: ' + st.best_loss.toFixed(6) + ' ---');
                        }
                    }
                }, 500);
            }
        } else {
            if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
        }
    }

    window.trainAction = trainAction;
    window.resetSession = resetSession;
    fetchViz();
})();
</script>";

