        diskCtx.strokeStyle = '#333'; diskCtx.lineWidth = 1.5; diskCtx.stroke();

        // Radial rings at hyperbolic distances
        for (let i = 1; i <= 4; i++) {
            diskCtx.beginPath(); diskCtx.arc(cx, cy, r*i/5, 0, 2*Math.PI);
