                sum += history[i];
                if (i >= wn) sum -= history[i - wn];
                if (i >= wn - 1) {
                    const avg = sum / wn;
                    const x = toX(i), y = toY(avg);
                    i === wn - 1 ? chartCtx.moveTo(x,y) : chartCtx.lineTo(x,y);
                }
            }
