use crate::web::templates::{layout, m_empty, m_header};
use crate::web::{AdminContext, NavItem};

/// Main learning dashboard page.
pub async fn dashboard(State(ctx): State<Arc<AdminContext>>) -> Markup {
    let Some(ref training) = ctx.training else {
        return layout(
            "Learn",
            NavItem::Learn,
            m_empty(
                "Training Not Configured",
                "Start the server with NEUMANN_LEARN=1 to enable the learning dashboard.",
            ),
        );
    };

    let stats = training.read().stats();

    let content = html! {
        (m_header("Hyperbolic Hierarchy Learning", Some("Riemannian SGD on the Poincare disk")))

        // Stat cards -- 6 columns
        div class="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-4" {
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Status" }
                div id="stat-status" class="text-base font-mono text-[var(--text-primary)]" {
                    @match stats.status {
                        tensor_learn::TrainingStatus::Idle => "IDLE",
                        tensor_learn::TrainingStatus::Running => "RUNNING",
                        tensor_learn::TrainingStatus::Paused => "PAUSED",
                        tensor_learn::TrainingStatus::Completed => "DONE",
                    }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Step" }
                div id="stat-step" class="text-base font-mono text-[var(--text-primary)]" {
                    (format!("{} / {}", stats.step, stats.total_steps))
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Loss" }
                div id="stat-loss" class="text-base font-mono text-[var(--text-primary)]" {
                    @if stats.loss < f64::MAX { (format!("{:.4}", stats.loss)) } @else { "-" }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Best" }
                div id="stat-best" class="text-base font-mono text-[var(--text-primary)]" {
                    @if stats.best_loss < f64::MAX { (format!("{:.4}", stats.best_loss)) } @else { "-" }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Accuracy" }
                div id="stat-acc" class="text-base font-mono text-[var(--text-primary)]" { "-" }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Root dist" }
                div id="stat-root" class="text-base font-mono text-[var(--text-primary)]" { "-" }
            }
        }

        // Controls
        div class="flex flex-wrap gap-2 mb-4 items-end" {
            button class="m-btn" onclick="trainAction('start')" { "Start" }
            button class="m-btn" onclick="trainAction('pause')" { "Pause" }
            button class="m-btn" onclick="singleStep()" { "Step" }
            div class="w-px h-6 bg-[var(--border)] mx-2" {}
            @for (id, label, val, w) in [
                ("in-steps", "Steps", "1000", "w-20"),
                ("in-lr", "LR", "0.1", "w-16"),
                ("in-depth", "Depth", "3", "w-14"),
                ("in-seed", "Seed", "42", "w-16"),
            ] {
                div {
                    label class="text-[10px] text-[var(--text-tertiary)] uppercase block mb-0.5" { (label) }
                    input id=(id) type="number" value=(val)
                        class={(w) " px-1.5 py-1 rounded bg-[var(--bg-secondary)] text-[var(--text-primary)] border border-[var(--border)] font-mono text-xs"} {}
                }
            }
            button class="m-btn" onclick="resetSession()" { "Reset" }
        }

        // Main grid: disk + chart
        div class="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-4" {
            // Poincare disk
            div class="m-card p-2" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Poincare Disk" }
                canvas id="poincare-canvas" width="520" height="520"
                    style="display: block; margin: 0 auto; background: #111; border-radius: 6px;" {}
            }
            // Loss chart + log
            div class="flex flex-col gap-4" {
                div class="m-card p-2" {
                    div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Loss Convergence" }
                    canvas id="loss-chart" width="520" height="220"
                        style="display: block; margin: 0 auto; background: #111; border-radius: 6px;" {}
                }
                div class="m-card p-2 flex flex-col flex-1" {
                    div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Training Log" }
                    pre id="log-output"
                        class="flex-1 overflow-y-auto font-mono text-[11px] leading-relaxed text-[var(--text-secondary)] bg-[#111] rounded p-2"
                        style="max-height: 260px; min-height: 180px; white-space: pre;" {
                        "Ready. Click Start or Step.\n"
                    }
                }
            }
        }

        (PreEscaped(LEARN_SCRIPT))
    };

    layout("Learn", NavItem::Learn, content)
}

/// Return current visualization data as JSON.
pub async fn viz_data(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    match session.to_viz_data() {
        Ok(data) => Json(data).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Return current training status as JSON.
pub async fn status(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    Json(session.stats()).into_response()
}

/// Start or resume training.
pub async fn start(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    session.start();
    StatusCode::OK
}

/// Toggle pause.
pub async fn pause(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    if session.status() == tensor_learn::TrainingStatus::Paused {
        session.resume();
    } else {
        session.pause();
    }
    StatusCode::OK
}

/// Execute a single training step.
pub async fn step(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let mut session = training.write();
    match session.step() {
        Ok(()) => Json(session.stats()).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Parameters for resetting the training session.
#[derive(Deserialize)]
pub struct ResetParams {
    /// Total steps for the new session.
    total_steps: Option<usize>,
    /// Learning rate for the new session.
    learning_rate: Option<f64>,
    /// RNG seed for the new session.
    seed: Option<u64>,
    /// Binary tree depth (default 3 = 15 nodes).
    depth: Option<u32>,
}

/// Reset training with a fresh binary-tree session.
pub async fn reset(
    State(ctx): State<Arc<AdminContext>>,
    Json(params): Json<ResetParams>,
) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let depth = params.depth.unwrap_or(3);
    let task = tensor_learn::HierarchyTask::binary_tree(depth);
    let config = tensor_learn::TrainingConfig {
        total_steps: params.total_steps.unwrap_or(200),
        learning_rate: params.learning_rate.unwrap_or(0.1),
        seed: params.seed.unwrap_or(42),
        dimension: 2,
        curvature: 1.0,
        ..tensor_learn::TrainingConfig::default()
    };

    match task.into_session(config) {
        Ok(session) => {
            *training.write() = session;
            StatusCode::OK.into_response()
        },
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Embedded JavaScript for the Poincare disk renderer, log, and controls.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const canvas = document.getElementById('poincare-canvas');
    const dCtx = canvas.getContext('2d');
    const logEl = document.getElementById('log-output');
    let vizData = null;
    let pollTimer = null;
    let lastLoggedStep = -1;

    function log(msg) {
        logEl.textContent += msg + '\n';
        logEl.scrollTop = logEl.scrollHeight;
    }

    function draw() {
        const w = canvas.width, h = canvas.height;
        const cx = w / 2, cy = h / 2;
        const r = Math.min(cx, cy) - 20;

        dCtx.clearRect(0, 0, w, h);

        // Unit circle
        dCtx.beginPath();
        dCtx.arc(cx, cy, r, 0, 2 * Math.PI);
        dCtx.strokeStyle = '#444';
        dCtx.lineWidth = 2;
        dCtx.stroke();

        // Radial grid + labels
        for (let i = 1; i <= 4; i++) {
            dCtx.beginPath();
            dCtx.arc(cx, cy, r * i / 5, 0, 2 * Math.PI);
            dCtx.strokeStyle = '#2a2a2a';
            dCtx.lineWidth = 0.5;
            dCtx.stroke();
        }

        if (!vizData) return;

        const nodeMap = {};
        for (const n of vizData.nodes) nodeMap[n.id] = n;

        // Edges
        for (const edge of vizData.edges) {
            const from = nodeMap[edge.from], to = nodeMap[edge.to];
            if (!from || !to) continue;
            dCtx.beginPath();
            dCtx.moveTo(cx + from.x * r, cy - from.y * r);
            dCtx.lineTo(cx + to.x * r, cy - to.y * r);
            dCtx.strokeStyle = '#555';
            dCtx.lineWidth = 1;
            dCtx.stroke();
        }

        // Nodes
        const colors = ['#60a5fa', '#34d399', '#fbbf24', '#f87171', '#a78bfa'];
        for (const n of vizData.nodes) {
            const x = cx + n.x * r, y = cy - n.y * r;
            const col = colors[n.level % colors.length];
            const sz = 8 - n.level;
            dCtx.beginPath();
            dCtx.arc(x, y, Math.max(sz, 3), 0, 2 * Math.PI);
            dCtx.fillStyle = col;
            dCtx.fill();
            dCtx.strokeStyle = '#fff';
            dCtx.lineWidth = 1;
            dCtx.stroke();
            dCtx.font = '11px Inter, sans-serif';
            dCtx.fillStyle = '#ccc';
            dCtx.textAlign = 'center';
            dCtx.fillText(n.label, x, y - sz - 4);
        }
    }

    function vizStats() {
        if (!vizData || !vizData.nodes.length) return null;
        const root = vizData.nodes.find(n => n.level === 0);
        const leaves = vizData.nodes.filter(n => n.level === 3);
        const leafAvg = leaves.length ? leaves.reduce((s,n) => s + n.distance_from_origin, 0) / leaves.length : 0;
        const leafMax = leaves.length ? Math.max(...leaves.map(n => n.distance_from_origin)) : 0;
        return {
            rootDist: root ? root.distance_from_origin : 0,
            leafAvg: leafAvg,
            leafMax: leafMax,
        };
    }

    async function fetchViz() {
        try {
            const resp = await fetch('/learn/viz');
            if (resp.ok) { vizData = await resp.json(); draw(); }
        } catch (_) {}
    }

    function updateStatsUI(st) {
        const el = id => document.getElementById(id);
        const statusName = {Idle:'IDLE', Running:'RUNNING', Paused:'PAUSED', Completed:'COMPLETED'};
        el('stat-status').textContent = statusName[st.status] || st.status;
        el('stat-step').textContent = st.step + ' / ' + st.total_steps;
        el('stat-loss').textContent = st.loss < 1e300 ? st.loss.toFixed(6) : '-';
        el('stat-best').textContent = st.best_loss < 1e300 ? st.best_loss.toFixed(6) : '-';
    }

    function logStep(st) {
        if (st.step <= lastLoggedStep) return;
        lastLoggedStep = st.step;
        const vs = vizStats();
        let line = 'Step ' + String(st.step).padStart(4) + '/' + st.total_steps;
        line += '  loss=' + st.loss.toFixed(4);
        line += '  edge=' + st.edge_loss.toFixed(4);
        line += '  radial=' + st.radial_loss.toFixed(4);
        line += '  neg=' + st.negative_loss.toFixed(4);
        if (vs) {
            line += '  root_d=' + vs.rootDist.toFixed(3);
            line += '  leaf_avg=' + vs.leafAvg.toFixed(3);
        }
        log(line);
    }

    async function trainAction(action) {
        try {
            await fetch('/learn/' + action, { method: 'POST' });
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateStatsUI(st);
                if (action === 'step') logStep(st);
                managePoll(st.status);
            }
        } catch (_) {}
    }

    async function resetSession() {
        const steps = parseInt(document.getElementById('in-steps').value) || 200;
        const lr = parseFloat(document.getElementById('in-lr').value) || 0.1;
        const seed = parseInt(document.getElementById('in-seed').value) || 42;
        try {
            await fetch('/learn/reset', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({total_steps: steps, learning_rate: lr, seed: seed})
            });
            logEl.textContent = '';
            lastLoggedStep = -1;
            log('--- Reset: steps=' + steps + ' lr=' + lr + ' seed=' + seed + ' ---');
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) updateStatsUI(await sr.json());
        } catch(e) { log('Reset error: ' + e); }
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetch('/learn/step', { method: 'POST' });
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateStatsUI(st);
                        logStep(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer);
                            pollTimer = null;
                            log('--- Training completed. Best loss: ' + st.best_loss.toFixed(6) + ' ---');
                        }
                    }
                }, 500);
            }
        } else {
            if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
        }
    }

    window.trainAction = trainAction;
    window.resetSession = resetSession;
    fetchViz();
})();
</script>";

