//! Grokking experiment: modular arithmetic on the Poincare disk.
//!
//! Trains a small MLP with hyperbolic embeddings on `a + b mod p`.
//! The model first memorizes the training set, then (after many steps)
//! suddenly generalizes to the held-out test set -- the grokking phenomenon.
//!
//! The embeddings live on the Poincare disk. Weight decay pulls them
//! toward the origin. After grokking, they self-organize into structure
//! that captures the cyclic group Z/pZ.

use rand::seq::SliceRandom;
use rand::{Rng, SeedableRng};
use serde::{Deserialize, Serialize};

use crate::poincare::PoincarePoint;
use crate::training::TrainingStatus;
use crate::viz::{VizData, VizEdge, VizMetadata, VizNode};

/// Maximum Poincare disk radius for projection.
const MAX_NORM: f64 = 1.0 - 1e-6;

/// Configuration for a grokking experiment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GrokConfig {
    /// Prime modulus for the arithmetic task.
    pub prime: usize,
    /// Hidden dimension of the MLP.
    pub hidden_dim: usize,
    /// Fraction of pairs used for training (rest is test).
    pub train_fraction: f64,
    /// Adam learning rate.
    pub learning_rate: f64,
    /// AdamW weight decay (1.0 is standard for grokking).
    pub weight_decay: f64,
    /// Poincare disk curvature.
    pub curvature: f64,
    /// RNG seed.
    pub seed: u64,
    /// Total training steps.
    pub total_steps: usize,
    /// Steps to advance per API call when running.
    pub steps_per_tick: usize,
}

impl Default for GrokConfig {
    fn default() -> Self {
        Self {
            prime: 31,
            hidden_dim: 128,
            train_fraction: 0.5,
            learning_rate: 1e-3,
            weight_decay: 1.0,
            curvature: 1.0,
            seed: 42,
            total_steps: 50_000,
            steps_per_tick: 20,
        }
    }
}

/// Statistics from a grokking experiment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GrokStats {
    /// Current step.
    pub step: usize,
    /// Total steps.
    pub total_steps: usize,
    /// Session status.
    pub status: TrainingStatus,
    /// Training loss (cross-entropy).
    pub train_loss: f64,
    /// Test loss.
    pub test_loss: f64,
    /// Training accuracy (fraction correct).
    pub train_acc: f64,
    /// Test accuracy (fraction correct).
    pub test_acc: f64,
    /// Training loss history.
    pub train_loss_history: Vec<f64>,
    /// Test loss history.
    pub test_loss_history: Vec<f64>,
    /// Training accuracy history.
    pub train_acc_history: Vec<f64>,
    /// Test accuracy history.
    pub test_acc_history: Vec<f64>,
}

/// A grokking experiment session.
pub struct GrokSession {
    config: GrokConfig,
    /// 2D Poincare embeddings, flat: `[x0, y0, x1, y1, ...]`.
    embeds: Vec<f64>,
    /// MLP weights: W1 (h*4), b1 (h), W2 (p*h), b2 (p).
    weights: Vec<f64>,
    /// Adam first moment for embeddings.
    embed_m: Vec<f64>,
    /// Adam second moment for embeddings.
    embed_v: Vec<f64>,
    /// Adam first moment for weights.
    weight_m: Vec<f64>,
    /// Adam second moment for weights.
    weight_v: Vec<f64>,
    /// Training triples `(a, b, c)` where `c = (a+b) % p`.
    train: Vec<(usize, usize, usize)>,
    /// Test triples.
    test: Vec<(usize, usize, usize)>,
    step: usize,
    status: TrainingStatus,
    train_loss: f64,
    test_loss: f64,
    train_acc: f64,
    test_acc: f64,
    train_loss_history: Vec<f64>,
    test_loss_history: Vec<f64>,
    train_acc_history: Vec<f64>,
    test_acc_history: Vec<f64>,
}

// -- Layout helpers for weight vector --
// W1: [0 .. h*4)
// b1: [h*4 .. h*4 + h)
// W2: [h*4 + h .. h*4 + h + p*h)
// b2: [h*4 + h + p*h .. h*4 + h + p*h + p)

fn w1_range(h: usize) -> std::ops::Range<usize> {
    0..h * 4
}
fn b1_range(h: usize) -> std::ops::Range<usize> {
    h * 4..h * 5
}
fn w2_range(p: usize, h: usize) -> std::ops::Range<usize> {
    h * 5..h * 5 + p * h
}
fn b2_range(p: usize, h: usize) -> std::ops::Range<usize> {
    h * 5 + p * h..h * 5 + p * h + p
}
fn weight_count(p: usize, h: usize) -> usize {
    h * 5 + p * h + p
}

impl GrokSession {
    /// Create a new grokking experiment.
    #[must_use]
    pub fn new(config: GrokConfig) -> Self {
        let p = config.prime;
        let h = config.hidden_dim;
        let mut rng = rand::rngs::StdRng::seed_from_u64(config.seed);

        // Random Poincare embeddings in [-0.05, 0.05]
        let embeds: Vec<f64> = (0..p * 2).map(|_| rng.random_range(-0.05..0.05)).collect();

        // Xavier-ish init for MLP weights
        let wc = weight_count(p, h);
        let mut weights = vec![0.0; wc];
        let scale1 = (2.0 / 4.0_f64).sqrt();
        #[allow(clippy::cast_precision_loss)]
        let scale2 = (2.0 / h as f64).sqrt();
        for w in &mut weights[w1_range(h)] {
            *w = rng.random_range(-scale1..scale1);
        }
        // b1 stays zero
        for w in &mut weights[w2_range(p, h)] {
            *w = rng.random_range(-scale2..scale2);
        }
        // b2 stays zero

        // Build all pairs and split train/test
        let mut all_triples: Vec<(usize, usize, usize)> = Vec::with_capacity(p * p);
        for a in 0..p {
            for b in 0..p {
                all_triples.push((a, b, (a + b) % p));
            }
        }
        all_triples.shuffle(&mut rng);
        #[allow(
            clippy::cast_possible_truncation,
            clippy::cast_sign_loss,
            clippy::cast_precision_loss
        )]
        let split = (all_triples.len() as f64 * config.train_fraction) as usize;
        let test = all_triples.split_off(split);
        let train = all_triples;

        Self {
            embeds: embeds.clone(),
            weights: weights.clone(),
            embed_m: vec![0.0; embeds.len()],
            embed_v: vec![0.0; embeds.len()],
            weight_m: vec![0.0; weights.len()],
            weight_v: vec![0.0; weights.len()],
            train,
            test,
            config,
            step: 0,
            status: TrainingStatus::Idle,
            train_loss: f64::MAX,
            test_loss: f64::MAX,
            train_acc: 0.0,
            test_acc: 0.0,
            train_loss_history: Vec::new(),
            test_loss_history: Vec::new(),
            train_acc_history: Vec::new(),
            test_acc_history: Vec::new(),
        }
    }

    /// Start or resume.
    pub fn start(&mut self) {
        if self.status != TrainingStatus::Completed {
            self.status = TrainingStatus::Running;
        }
    }

    /// Pause.
    pub fn pause(&mut self) {
        if self.status == TrainingStatus::Running {
            self.status = TrainingStatus::Paused;
        }
    }

    /// Current status.
    #[must_use]
    pub const fn status(&self) -> TrainingStatus {
        self.status
    }

    /// Run one or more training steps (controlled by `steps_per_tick`).
    pub fn step(&mut self) {
        if self.status == TrainingStatus::Completed {
            return;
        }
        if self.status != TrainingStatus::Running {
            self.status = TrainingStatus::Running;
        }

        let ticks = if self.status == TrainingStatus::Running {
            self.config.steps_per_tick
        } else {
            1
        };

        for _ in 0..ticks {
            if self.step >= self.config.total_steps {
                self.status = TrainingStatus::Completed;
                break;
            }
            self.train_step();
            self.step += 1;
        }

        // Evaluate on both sets
        let (tl, ta) = self.evaluate(&self.train.clone());
        let (vl, va) = self.evaluate(&self.test.clone());
        self.train_loss = tl;
        self.train_acc = ta;
        self.test_loss = vl;
        self.test_acc = va;
        self.train_loss_history.push(tl);
        self.test_loss_history.push(tl);
        self.train_acc_history.push(ta);
        self.test_acc_history.push(va);

        if self.step >= self.config.total_steps {
            self.status = TrainingStatus::Completed;
        }
    }

    /// Run a single Step button press (1 step only).
    pub fn single_step(&mut self) {
        if self.status == TrainingStatus::Completed {
            return;
        }
        if self.step < self.config.total_steps {
            self.train_step();
            self.step += 1;
        }
        let (tl, ta) = self.evaluate(&self.train.clone());
        let (vl, va) = self.evaluate(&self.test.clone());
        self.train_loss = tl;
        self.train_acc = ta;
        self.test_loss = vl;
        self.test_acc = va;
        self.train_loss_history.push(tl);
        self.test_loss_history.push(tl);
        self.train_acc_history.push(ta);
        self.test_acc_history.push(va);
        if self.step >= self.config.total_steps {
            self.status = TrainingStatus::Completed;
        }
    }

    /// Current statistics.
    #[must_use]
    pub fn stats(&self) -> GrokStats {
        GrokStats {
            step: self.step,
            total_steps: self.config.total_steps,
            status: self.status,
            train_loss: self.train_loss,
            test_loss: self.test_loss,
            train_acc: self.train_acc,
            test_acc: self.test_acc,
            train_loss_history: self.train_loss_history.clone(),
            test_loss_history: self.test_loss_history.clone(),
            train_acc_history: self.train_acc_history.clone(),
            test_acc_history: self.test_acc_history.clone(),
        }
    }

    /// Export embeddings as viz data for the Poincare disk renderer.
    #[must_use]
    pub fn to_viz_data(&self) -> VizData {
        let p = self.config.prime;
        let nodes: Vec<VizNode> = (0..p)
            .map(|i| {
                let x = self.embeds[i * 2];
                let y = self.embeds[i * 2 + 1];
                let point = PoincarePoint::new(vec![x, y]);
                let origin = PoincarePoint::origin(2);
                VizNode {
                    id: format!("{i}"),
                    label: format!("{i}"),
                    x,
                    y,
                    #[allow(clippy::cast_possible_truncation)]
                    level: (i * 5 / p) as u32, // color banding
                    distance_from_origin: point.distance(&origin, self.config.curvature),
                }
            })
            .collect();

        VizData {
            nodes,
            edges: Vec::new(),
            metadata: VizMetadata {
                entry_count: p,
                edge_count: 0,
                curvature: self.config.curvature,
                dimension: 2,
            },
        }
    }

    // -- Core training --

    /// One gradient step on the full training set.
    fn train_step(&mut self) {
        let p = self.config.prime;
        let h = self.config.hidden_dim;
        let lr = self.config.learning_rate;
        let wd = self.config.weight_decay;

        let mut embed_grad = vec![0.0; self.embeds.len()];
        let mut weight_grad = vec![0.0; self.weights.len()];

        // Accumulate gradients over all training triples
        for &(a, b, c_true) in &self.train.clone() {
            self.backward(a, b, c_true, &mut embed_grad, &mut weight_grad);
        }

        // Normalize by batch size
        #[allow(clippy::cast_precision_loss)]
        let n = self.train.len() as f64;
        for g in &mut embed_grad {
            *g /= n;
        }
        for g in &mut weight_grad {
            *g /= n;
        }

        // AdamW update for embeddings
        self.step_adam(
            &mut self.embeds.clone(),
            &embed_grad,
            &mut self.embed_m,
            &mut self.embed_v,
            lr,
            wd,
            true,
        );

        // AdamW update for MLP weights
        let mut w = self.weights.clone();
        self.step_adam(
            &mut w,
            &weight_grad,
            &mut self.weight_m,
            &mut self.weight_v,
            lr,
            wd,
            false,
        );
        self.weights = w;

        // Project embeddings back to Poincare disk
        for i in 0..p {
            let x = self.embeds[i * 2];
            let y = self.embeds[i * 2 + 1];
            let norm = x.hypot(y);
            if norm >= MAX_NORM {
                let s = MAX_NORM / norm;
                self.embeds[i * 2] *= s;
                self.embeds[i * 2 + 1] *= s;
            }
        }
    }

    /// AdamW parameter update.
    #[allow(clippy::too_many_arguments)]
    fn step_adam(
        &self,
        params: &mut Vec<f64>,
        grads: &[f64],
        m: &mut Vec<f64>,
        v: &mut Vec<f64>,
        lr: f64,
        wd: f64,
        is_embed: bool,
    ) {
        let beta1 = 0.9;
        let beta2 = 0.98;
        let eps = 1e-8;
        #[allow(clippy::cast_possible_truncation)]
        let t = (self.step + 1) as i32;
        let bc1 = 1.0 - beta1.powi(t);
        let bc2 = 1.0 - beta2.powi(t);

        for i in 0..params.len() {
            m[i] = beta1.mul_add(m[i], (1.0 - beta1) * grads[i]);
            v[i] = beta2.mul_add(v[i], (1.0 - beta2) * grads[i] * grads[i]);
            let m_hat = m[i] / bc1;
            let v_hat = v[i] / bc2;
            let update = m_hat / (v_hat.sqrt() + eps);
            // AdamW: decoupled weight decay
            params[i] -= lr * (update + wd * params[i]);
        }

        if is_embed {
            // Write back to self.embeds (we passed a clone)
            // This is a workaround for borrow checker
        }
    }

    /// Forward pass: returns logits (p values) and loss.
    fn forward(&self, a: usize, b: usize, c_true: usize) -> (Vec<f64>, f64) {
        let h = self.config.hidden_dim;
        let p = self.config.prime;

        // Input: [embed(a).x, embed(a).y, embed(b).x, embed(b).y]
        let input = [
            self.embeds[a * 2],
            self.embeds[a * 2 + 1],
            self.embeds[b * 2],
            self.embeds[b * 2 + 1],
        ];

        // pre_h = W1 @ input + b1
        let w1 = &self.weights[w1_range(h)];
        let b1 = &self.weights[b1_range(h)];
        let mut pre_h = vec![0.0; h];
        for i in 0..h {
            let mut sum = b1[i];
            for j in 0..4 {
                sum = w1[i * 4 + j].mul_add(input[j], sum);
            }
            pre_h[i] = sum;
        }

        // h = ReLU(pre_h)
        let hidden: Vec<f64> = pre_h.iter().map(|&x| x.max(0.0)).collect();

        // logits = W2 @ hidden + b2
        let w2 = &self.weights[w2_range(p, h)];
        let b2 = &self.weights[b2_range(p, h)];
        let mut logits = vec![0.0; p];
        for i in 0..p {
            let mut sum = b2[i];
            for j in 0..h {
                sum = w2[i * h + j].mul_add(hidden[j], sum);
            }
            logits[i] = sum;
        }

        // Stable softmax + cross-entropy
        let max_logit = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        let exp_sum: f64 = logits.iter().map(|&l| (l - max_logit).exp()).sum();
        let loss = -(logits[c_true] - max_logit) + exp_sum.ln();

        (logits, loss)
    }

    /// Backward pass: accumulate gradients for one triple.
    fn backward(
        &self,
        a: usize,
        b: usize,
        c_true: usize,
        embed_grad: &mut [f64],
        weight_grad: &mut [f64],
    ) {
        let h = self.config.hidden_dim;
        let p = self.config.prime;

        // -- Forward (save intermediates) --
        let input = [
            self.embeds[a * 2],
            self.embeds[a * 2 + 1],
            self.embeds[b * 2],
            self.embeds[b * 2 + 1],
        ];

        let w1 = &self.weights[w1_range(h)];
        let b1 = &self.weights[b1_range(h)];
        let mut pre_h = vec![0.0; h];
        for i in 0..h {
            let mut sum = b1[i];
            for j in 0..4 {
                sum = w1[i * 4 + j].mul_add(input[j], sum);
            }
            pre_h[i] = sum;
        }
        let hidden: Vec<f64> = pre_h.iter().map(|&x| x.max(0.0)).collect();

        let w2 = &self.weights[w2_range(p, h)];
        let b2 = &self.weights[b2_range(p, h)];
        let mut logits = vec![0.0; p];
        for i in 0..p {
            let mut sum = b2[i];
            for j in 0..h {
                sum = w2[i * h + j].mul_add(hidden[j], sum);
            }
            logits[i] = sum;
        }

        // Softmax probabilities
        let max_l = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        let exps: Vec<f64> = logits.iter().map(|&l| (l - max_l).exp()).collect();
        let sum_exp: f64 = exps.iter().sum();
        let probs: Vec<f64> = exps.iter().map(|&e| e / sum_exp).collect();

        // -- Backward --
        // d_logits = probs - one_hot(c_true)
        let mut d_logits = probs;
        d_logits[c_true] -= 1.0;

        // d_W2, d_b2
        let w2_off = w2_range(p, h).start;
        let b2_off = b2_range(p, h).start;
        for i in 0..p {
            weight_grad[b2_off + i] += d_logits[i];
            for j in 0..h {
                weight_grad[w2_off + i * h + j] += d_logits[i] * hidden[j];
            }
        }

        // d_hidden = W2^T @ d_logits
        let mut d_hidden = vec![0.0; h];
        for j in 0..h {
            for i in 0..p {
                d_hidden[j] += w2[i * h + j] * d_logits[i];
            }
        }

        // d_pre_h (ReLU backward)
        let d_pre_h: Vec<f64> = d_hidden
            .iter()
            .zip(pre_h.iter())
            .map(|(&dh, &ph)| if ph > 0.0 { dh } else { 0.0 })
            .collect();

        // d_W1, d_b1
        let w1_off = w1_range(h).start;
        let b1_off = b1_range(h).start;
        for i in 0..h {
            weight_grad[b1_off + i] += d_pre_h[i];
            for j in 0..4 {
                weight_grad[w1_off + i * 4 + j] += d_pre_h[i] * input[j];
            }
        }

        // d_input = W1^T @ d_pre_h
        let mut d_input = [0.0; 4];
        for j in 0..4 {
            for i in 0..h {
                d_input[j] += w1[i * 4 + j] * d_pre_h[i];
            }
        }

        // Accumulate embedding gradients
        embed_grad[a * 2] += d_input[0];
        embed_grad[a * 2 + 1] += d_input[1];
        embed_grad[b * 2] += d_input[2];
        embed_grad[b * 2 + 1] += d_input[3];
    }

    /// Evaluate loss and accuracy on a set of triples.
    fn evaluate(&self, triples: &[(usize, usize, usize)]) -> (f64, f64) {
        if triples.is_empty() {
            return (0.0, 0.0);
        }
        let mut total_loss = 0.0;
        let mut correct = 0_usize;

        for &(a, b, c_true) in triples {
            let (logits, loss) = self.forward(a, b, c_true);
            total_loss += loss;
            let pred = logits
                .iter()
                .enumerate()
                .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
                .map_or(0, |(i, _)| i);
            if pred == c_true {
                correct += 1;
            }
        }

        #[allow(clippy::cast_precision_loss)]
        let n = triples.len() as f64;
        (total_loss / n, correct as f64 / n)
    }
}

// Fix the borrow-checker issue in train_step: we need to update embeds in place
// through the Adam optimizer. Restructure to avoid the clone workaround.
impl GrokSession {
    /// Full training step with proper in-place Adam updates.
    fn step_adam_inplace(
        params: &mut [f64],
        grads: &[f64],
        m: &mut [f64],
        v: &mut [f64],
        lr: f64,
        wd: f64,
        step: usize,
    ) {
        let beta1 = 0.9;
        let beta2 = 0.98;
        let eps = 1e-8;
        #[allow(clippy::cast_possible_truncation)]
        let t = (step + 1) as i32;
        let bc1 = 1.0 - beta1.powi(t);
        let bc2 = 1.0 - beta2.powi(t);

        for i in 0..params.len() {
            m[i] = beta1.mul_add(m[i], (1.0 - beta1) * grads[i]);
            v[i] = beta2.mul_add(v[i], (1.0 - beta2) * grads[i] * grads[i]);
            let m_hat = m[i] / bc1;
            let v_hat = v[i] / bc2;
            let update = m_hat / (v_hat.sqrt() + eps);
            params[i] -= lr * (update + wd * params[i]);
        }
    }
}

// Replace train_step to use the inplace version
impl GrokSession {
    /// Proper training step without clone workarounds.
    fn train_step(&mut self) {
        let p = self.config.prime;
        let lr = self.config.learning_rate;
        let wd = self.config.weight_decay;

        let mut embed_grad = vec![0.0; self.embeds.len()];
        let mut weight_grad = vec![0.0; self.weights.len()];

        let train_copy = self.train.clone();
        for &(a, b, c_true) in &train_copy {
            self.backward(a, b, c_true, &mut embed_grad, &mut weight_grad);
        }

        #[allow(clippy::cast_precision_loss)]
        let n = train_copy.len() as f64;
        for g in &mut embed_grad {
            *g /= n;
        }
        for g in &mut weight_grad {
            *g /= n;
        }

        let step = self.step;
        Self::step_adam_inplace(
            &mut self.embeds,
            &embed_grad,
            &mut self.embed_m,
            &mut self.embed_v,
            lr,
            wd,
            step,
        );
        Self::step_adam_inplace(
            &mut self.weights,
            &weight_grad,
            &mut self.weight_m,
            &mut self.weight_v,
            lr,
            wd,
            step,
        );

        // Project embeddings back to Poincare disk
        for i in 0..p {
            let x = self.embeds[i * 2];
            let y = self.embeds[i * 2 + 1];
            let norm = x.hypot(y);
            if norm >= MAX_NORM {
                let s = MAX_NORM / norm;
                self.embeds[i * 2] *= s;
                self.embeds[i * 2 + 1] *= s;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn grok_session_creates() {
        let s = GrokSession::new(GrokConfig::default());
        assert_eq!(s.step, 0);
        assert_eq!(s.train.len() + s.test.len(), 31 * 31);
    }

    #[test]
    fn forward_produces_finite_loss() {
        let s = GrokSession::new(GrokConfig::default());
        let (logits, loss) = s.forward(0, 1, 1);
        assert_eq!(logits.len(), 31);
        assert!(loss.is_finite(), "loss should be finite: {loss}");
    }

    #[test]
    fn single_step_advances() {
        let mut s = GrokSession::new(GrokConfig::default());
        s.single_step();
        assert_eq!(s.step, 1);
        assert!(s.train_loss.is_finite());
        assert!(s.train_acc >= 0.0);
    }

    #[test]
    fn multi_step_advances() {
        let mut s = GrokSession::new(GrokConfig {
            steps_per_tick: 5,
            total_steps: 100,
            ..GrokConfig::default()
        });
        s.step();
        assert_eq!(s.step, 5);
    }

    #[test]
    fn embeddings_stay_in_disk() {
        let mut s = GrokSession::new(GrokConfig {
            total_steps: 50,
            steps_per_tick: 50,
            ..GrokConfig::default()
        });
        s.step();
        let p = s.config.prime;
        for i in 0..p {
            let x = s.embeds[i * 2];
            let y = s.embeds[i * 2 + 1];
            assert!(x.hypot(y) < 1.0, "embedding {i} escaped disk: ({x}, {y})");
        }
    }

    #[test]
    fn train_loss_decreases() {
        let mut s = GrokSession::new(GrokConfig {
            total_steps: 200,
            steps_per_tick: 50,
            ..GrokConfig::default()
        });
        s.step();
        let loss1 = s.train_loss;
        s.step();
        s.step();
        s.step();
        let loss2 = s.train_loss;
        assert!(
            loss2 < loss1,
            "train loss should decrease: {loss1} -> {loss2}"
        );
    }

    #[test]
    fn stats_and_viz() {
        let s = GrokSession::new(GrokConfig::default());
        let stats = s.stats();
        assert_eq!(stats.step, 0);
        let viz = s.to_viz_data();
        assert_eq!(viz.nodes.len(), 31);
    }

    #[test]
    fn reproducible() {
        let run = || {
            let mut s = GrokSession::new(GrokConfig {
                total_steps: 20,
                steps_per_tick: 20,
                ..GrokConfig::default()
            });
            s.step();
            s.train_loss
        };
        let l1 = run();
        let l2 = run();
        assert!(
            (l1 - l2).abs() < 1e-12,
            "same seed should produce same loss: {l1} vs {l2}"
        );
    }

    #[test]
    fn completed_at_total_steps() {
        let mut s = GrokSession::new(GrokConfig {
            total_steps: 10,
            steps_per_tick: 10,
            ..GrokConfig::default()
        });
        s.step();
        assert_eq!(s.status(), TrainingStatus::Completed);
    }
}

