// SPDX-License-Identifier: MIT OR Apache-2.0
//! Geometric learning dashboard handlers.
//!
//! Renders a Poincare disk visualization with training controls,
//! a structured log panel, and configurable parameters.

use std::sync::Arc;

use axum::extract::State;
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use maud::{html, Markup, PreEscaped};
use serde::Deserialize;

use crate::web::templates::{layout, m_empty, m_header};
use crate::web::{AdminContext, NavItem};

/// Main learning dashboard page.
pub async fn dashboard(State(ctx): State<Arc<AdminContext>>) -> Markup {
    let Some(ref training) = ctx.training else {
        return layout(
            "Learn",
            NavItem::Learn,
            m_empty(
                "Training Not Configured",
                "Start the server with NEUMANN_LEARN=1 to enable the learning dashboard.",
            ),
        );
    };

    let stats = training.read().stats();

    let content = html! {
        (m_header("Hyperbolic Hierarchy Learning", Some("Riemannian SGD on the Poincare disk")))

        // Stat cards -- 6 columns
        div class="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-4" {
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Status" }
                div id="stat-status" class="text-base font-mono text-[var(--text-primary)]" {
                    @match stats.status {
                        tensor_learn::TrainingStatus::Idle => "IDLE",
                        tensor_learn::TrainingStatus::Running => "RUNNING",
                        tensor_learn::TrainingStatus::Paused => "PAUSED",
                        tensor_learn::TrainingStatus::Completed => "DONE",
                    }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Step" }
                div id="stat-step" class="text-base font-mono text-[var(--text-primary)]" {
                    (format!("{} / {}", stats.step, stats.total_steps))
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Loss" }
                div id="stat-loss" class="text-base font-mono text-[var(--text-primary)]" {
                    @if stats.loss < f64::MAX { (format!("{:.4}", stats.loss)) } @else { "-" }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Best" }
                div id="stat-best" class="text-base font-mono text-[var(--text-primary)]" {
                    @if stats.best_loss < f64::MAX { (format!("{:.4}", stats.best_loss)) } @else { "-" }
                }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Accuracy" }
                div id="stat-acc" class="text-base font-mono text-[var(--text-primary)]" { "-" }
            }
            div class="m-card" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1" { "Root dist" }
                div id="stat-root" class="text-base font-mono text-[var(--text-primary)]" { "-" }
            }
        }

        // Controls
        div class="flex flex-wrap gap-2 mb-4 items-end" {
            button class="m-btn" onclick="trainAction('start')" { "Start" }
            button class="m-btn" onclick="trainAction('pause')" { "Pause" }
            button class="m-btn" onclick="singleStep()" { "Step" }
            div class="w-px h-6 bg-[var(--border)] mx-2" {}
            @for (id, label, val, w) in [
                ("in-steps", "Steps", "1000", "w-20"),
                ("in-lr", "LR", "0.1", "w-16"),
                ("in-depth", "Depth", "3", "w-14"),
                ("in-seed", "Seed", "42", "w-16"),
            ] {
                div {
                    label class="text-[10px] text-[var(--text-tertiary)] uppercase block mb-0.5" { (label) }
                    input id=(id) type="number" value=(val)
                        class={(w) " px-1.5 py-1 rounded bg-[var(--bg-secondary)] text-[var(--text-primary)] border border-[var(--border)] font-mono text-xs"} {}
                }
            }
            button class="m-btn" onclick="resetSession()" { "Reset" }
        }

        // Main grid: disk + chart
        div class="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-4" {
            // Poincare disk
            div class="m-card p-2" {
                div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Poincare Disk" }
                canvas id="poincare-canvas" width="520" height="520"
                    style="display: block; margin: 0 auto; background: #111; border-radius: 6px;" {}
            }
            // Loss chart + log
            div class="flex flex-col gap-4" {
                div class="m-card p-2" {
                    div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Loss Convergence" }
                    canvas id="loss-chart" width="520" height="220"
                        style="display: block; margin: 0 auto; background: #111; border-radius: 6px;" {}
                }
                div class="m-card p-2 flex flex-col flex-1" {
                    div class="text-[10px] text-[var(--text-tertiary)] uppercase tracking-wider mb-1 px-1" { "Training Log" }
                    pre id="log-output"
                        class="flex-1 overflow-y-auto font-mono text-[11px] leading-relaxed text-[var(--text-secondary)] bg-[#111] rounded p-2"
                        style="max-height: 260px; min-height: 180px; white-space: pre;" {
                        "Ready. Click Start or Step.\n"
                    }
                }
            }
        }

        (PreEscaped(LEARN_SCRIPT))
    };

    layout("Learn", NavItem::Learn, content)
}

/// Return current visualization data as JSON.
pub async fn viz_data(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    match session.to_viz_data() {
        Ok(data) => Json(data).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Return current training status as JSON.
pub async fn status(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let session = training.read();
    Json(session.stats()).into_response()
}

/// Start or resume training.
pub async fn start(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    session.start();
    StatusCode::OK
}

/// Toggle pause.
pub async fn pause(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND;
    };

    let mut session = training.write();
    if session.status() == tensor_learn::TrainingStatus::Paused {
        session.resume();
    } else {
        session.pause();
    }
    StatusCode::OK
}

/// Execute a single training step.
pub async fn step(State(ctx): State<Arc<AdminContext>>) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no training session"})),
        )
            .into_response();
    };

    let mut session = training.write();
    match session.step() {
        Ok(()) => Json(session.stats()).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Parameters for resetting the training session.
#[derive(Deserialize)]
pub struct ResetParams {
    /// Total steps for the new session.
    total_steps: Option<usize>,
    /// Learning rate for the new session.
    learning_rate: Option<f64>,
    /// RNG seed for the new session.
    seed: Option<u64>,
    /// Binary tree depth (default 3 = 15 nodes).
    depth: Option<u32>,
}

/// Reset training with a fresh binary-tree session.
pub async fn reset(
    State(ctx): State<Arc<AdminContext>>,
    Json(params): Json<ResetParams>,
) -> impl IntoResponse {
    let Some(ref training) = ctx.training else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let depth = params.depth.unwrap_or(3);
    let task = tensor_learn::HierarchyTask::binary_tree(depth);
    let config = tensor_learn::TrainingConfig {
        total_steps: params.total_steps.unwrap_or(200),
        learning_rate: params.learning_rate.unwrap_or(0.1),
        seed: params.seed.unwrap_or(42),
        dimension: 2,
        curvature: 1.0,
        ..tensor_learn::TrainingConfig::default()
    };

    match task.into_session(config) {
        Ok(session) => {
            *training.write() = session;
            StatusCode::OK.into_response()
        },
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({"error": e.to_string()})),
        )
            .into_response(),
    }
}

/// Embedded JavaScript for the research dashboard.
const LEARN_SCRIPT: &str = r"<script>
(function() {
    const diskCanvas = document.getElementById('poincare-canvas');
    const diskCtx   = diskCanvas.getContext('2d');
    const chartCanvas = document.getElementById('loss-chart');
    const chartCtx  = chartCanvas.getContext('2d');
    const logEl     = document.getElementById('log-output');
    let vizData = null, pollTimer = null, lastStep = -1;

    const el = id => document.getElementById(id);
    const pad = (n, w) => String(n).padStart(w);
    const f = (v, d) => v.toFixed(d);

    function log(msg) { logEl.textContent += msg + '\n'; logEl.scrollTop = logEl.scrollHeight; }

    // -- Poincare disk renderer --
    function drawDisk() {
        const w = diskCanvas.width, h = diskCanvas.height;
        const cx = w/2, cy = h/2, r = Math.min(cx,cy) - 16;
        diskCtx.clearRect(0, 0, w, h);

        // Boundary
        diskCtx.beginPath(); diskCtx.arc(cx, cy, r, 0, 2*Math.PI);
        diskCtx.strokeStyle = '#333'; diskCtx.lineWidth = 1.5; diskCtx.stroke();

        // Radial rings at hyperbolic distances
        for (let i = 1; i <= 4; i++) {
            diskCtx.beginPath(); diskCtx.arc(cx, cy, r*i/5, 0, 2*Math.PI);
            diskCtx.strokeStyle = '#1a1a1a'; diskCtx.lineWidth = 0.5; diskCtx.stroke();
        }

        if (!vizData || !vizData.nodes.length) return;
        const nm = {}; for (const n of vizData.nodes) nm[n.id] = n;

        // Edges
        diskCtx.strokeStyle = '#333'; diskCtx.lineWidth = 0.8;
        for (const e of vizData.edges) {
            const a = nm[e.from], b = nm[e.to]; if (!a||!b) continue;
            diskCtx.beginPath();
            diskCtx.moveTo(cx + a.x*r, cy - a.y*r);
            diskCtx.lineTo(cx + b.x*r, cy - b.y*r);
            diskCtx.stroke();
        }

        // Nodes by level
        const pal = ['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#ec4899'];
        for (const n of vizData.nodes) {
            const x = cx + n.x*r, y = cy - n.y*r;
            const col = pal[n.level % pal.length];
            const sz = Math.max(7 - n.level, 3);
            diskCtx.beginPath(); diskCtx.arc(x, y, sz, 0, 2*Math.PI);
            diskCtx.fillStyle = col; diskCtx.fill();
            diskCtx.strokeStyle = '#000'; diskCtx.lineWidth = 0.5; diskCtx.stroke();
            diskCtx.font = '10px monospace'; diskCtx.fillStyle = '#888';
            diskCtx.textAlign = 'center'; diskCtx.fillText(n.label, x, y - sz - 3);
        }
    }

    // -- Loss chart renderer --
    function drawChart(history) {
        const w = chartCanvas.width, h = chartCanvas.height;
        const P = {l:48, r:8, t:12, b:22};
        const pw = w-P.l-P.r, ph = h-P.t-P.b;
        chartCtx.clearRect(0, 0, w, h);

        if (!history || history.length < 2) {
            chartCtx.fillStyle = '#444'; chartCtx.font = '12px monospace';
            chartCtx.textAlign = 'center'; chartCtx.fillText('Awaiting data...', w/2, h/2);
            return;
        }

        const mn = Math.min(...history), mx = Math.max(...history);
        const rng = mx - mn || 1;
        const toX = i => P.l + (i/(history.length-1))*pw;
        const toY = v => P.t + ((mx-v)/rng)*ph;

        // Grid
        chartCtx.strokeStyle = '#222'; chartCtx.lineWidth = 0.5;
        for (let i = 0; i <= 4; i++) {
            const y = P.t + ph*i/4;
            chartCtx.beginPath(); chartCtx.moveTo(P.l, y); chartCtx.lineTo(w-P.r, y); chartCtx.stroke();
        }

        // Loss line
        chartCtx.beginPath(); chartCtx.strokeStyle = '#3b82f6'; chartCtx.lineWidth = 1.5;
        for (let i = 0; i < history.length; i++) {
            const x = toX(i), y = toY(history[i]);
            i === 0 ? chartCtx.moveTo(x,y) : chartCtx.lineTo(x,y);
        }
        chartCtx.stroke();

        // Moving average (window 20)
        if (history.length > 20) {
            chartCtx.beginPath(); chartCtx.strokeStyle = '#f59e0b'; chartCtx.lineWidth = 1.5;
            const wn = 20;
            let sum = 0;
            for (let i = 0; i < history.length; i++) {
                sum += history[i];
                if (i >= wn) sum -= history[i - wn];
                if (i >= wn - 1) {
                    const avg = sum / wn;
                    const x = toX(i), y = toY(avg);
                    i === wn - 1 ? chartCtx.moveTo(x,y) : chartCtx.lineTo(x,y);
                }
            }
            chartCtx.stroke();
        }

        // Axis labels
        chartCtx.fillStyle = '#555'; chartCtx.font = '9px monospace'; chartCtx.textAlign = 'right';
        chartCtx.fillText(f(mx,3), P.l-4, P.t+8);
        chartCtx.fillText(f(mn,3), P.l-4, P.t+ph+3);
        chartCtx.textAlign = 'center';
        chartCtx.fillText('step', w/2, h-3);
        chartCtx.textAlign = 'left';
        chartCtx.fillText(history.length.toString(), toX(history.length-1)-10, h-3);

        // Legend
        chartCtx.fillStyle = '#3b82f6'; chartCtx.fillRect(P.l+4, P.t+2, 12, 3);
        chartCtx.fillStyle = '#666'; chartCtx.font = '9px monospace'; chartCtx.textAlign = 'left';
        chartCtx.fillText('loss', P.l+20, P.t+8);
        if (history.length > 20) {
            chartCtx.fillStyle = '#f59e0b'; chartCtx.fillRect(P.l+54, P.t+2, 12, 3);
            chartCtx.fillStyle = '#666'; chartCtx.fillText('ma20', P.l+70, P.t+8);
        }
    }

    // -- Metrics computed from viz data --
    function metrics() {
        if (!vizData || !vizData.nodes.length) return null;
        const nm = {}; for (const n of vizData.nodes) nm[n.id] = n;
        let correct = 0, total = 0;
        for (const e of vizData.edges) {
            const p = nm[e.from], c = nm[e.to]; if (!p||!c) continue;
            total++; if (p.distance_from_origin < c.distance_from_origin) correct++;
        }
        const root = vizData.nodes.find(n => n.level === 0);
        const maxLevel = Math.max(...vizData.nodes.map(n => n.level));
        const leaves = vizData.nodes.filter(n => n.level === maxLevel);
        const leafAvg = leaves.length ? leaves.reduce((s,n) => s + n.distance_from_origin, 0)/leaves.length : 0;
        return {
            acc: total ? correct/total : 0,
            rootDist: root ? root.distance_from_origin : 0,
            leafAvg, total, correct,
        };
    }

    // -- Fetching --
    async function fetchViz() {
        try {
            const r = await fetch('/learn/viz');
            if (r.ok) { vizData = await r.json(); drawDisk(); }
        } catch(_) {}
    }

    // -- UI updates --
    function updateUI(st) {
        const sn = {Idle:'IDLE',Running:'RUNNING',Paused:'PAUSED',Completed:'DONE'};
        el('stat-status').textContent = sn[st.status] || st.status;
        el('stat-step').textContent = st.step + ' / ' + st.total_steps;
        el('stat-loss').textContent = st.loss < 1e300 ? f(st.loss,4) : '-';
        el('stat-best').textContent = st.best_loss < 1e300 ? f(st.best_loss,4) : '-';
        const m = metrics();
        if (m) {
            el('stat-acc').textContent = Math.round(m.acc*100) + '%';
            el('stat-root').textContent = f(m.rootDist, 3);
        }
        drawChart(st.loss_history);
    }

    function logStep(st) {
        if (st.step <= lastStep) return;
        lastStep = st.step;
        const m = metrics();
        let s = pad(st.step,5) + '/' + pad(st.total_steps,-1);
        s += '  loss=' + f(st.loss,4);
        s += '  E=' + f(st.edge_loss,4);
        s += '  R=' + f(st.radial_loss,4);
        s += '  N=' + f(st.negative_loss,4);
        if (m) s += '  acc=' + pad(Math.round(m.acc*100),3) + '%  root=' + f(m.rootDist,3) + '  leaf=' + f(m.leafAvg,3);
        log(s);
    }

    // -- Actions --
    async function trainAction(action) {
        try {
            // Auto-reset if starting a completed session
            if (action === 'start') {
                const sr = await fetch('/learn/status');
                if (sr.ok) {
                    const st = await sr.json();
                    if (st.status === 'Completed') { await doReset(); }
                }
            }
            await fetch('/learn/' + action, { method: 'POST' });
            await fetchViz();
            const sr = await fetch('/learn/status');
            if (sr.ok) {
                const st = await sr.json();
                updateUI(st);
                managePoll(st.status);
            }
        } catch(_) {}
    }

    async function singleStep() {
        try {
            const r = await fetch('/learn/step', { method: 'POST' });
            await fetchViz();
            if (r.ok) { const st = await r.json(); updateUI(st); logStep(st); }
        } catch(_) {}
    }

    function getParams() {
        return {
            total_steps: parseInt(el('in-steps').value) || 1000,
            learning_rate: parseFloat(el('in-lr').value) || 0.1,
            seed: parseInt(el('in-seed').value) || 42,
            depth: parseInt(el('in-depth').value) || 3,
        };
    }

    async function doReset() {
        const p = getParams();
        await fetch('/learn/reset', {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify(p),
        });
        lastStep = -1;
    }

    async function resetSession() {
        const p = getParams();
        logEl.textContent = '';
        log('--- Reset: steps=' + p.total_steps + ' lr=' + p.learning_rate + ' depth=' + p.depth + ' seed=' + p.seed + ' ---');
        await doReset();
        await fetchViz();
        const sr = await fetch('/learn/status');
        if (sr.ok) updateUI(await sr.json());
    }

    function managePoll(status) {
        if (status === 'Running') {
            if (!pollTimer) {
                pollTimer = setInterval(async () => {
                    await fetch('/learn/step', { method: 'POST' });
                    await fetchViz();
                    const sr = await fetch('/learn/status');
                    if (sr.ok) {
                        const st = await sr.json();
                        updateUI(st);
                        logStep(st);
                        if (st.status !== 'Running') {
                            clearInterval(pollTimer); pollTimer = null;
                            const m = metrics();
                            log('--- Done. best=' + f(st.best_loss,4) + (m ? ' acc=' + Math.round(m.acc*100) + '%' : '') + ' ---');
                        }
                    }
                }, 200);
            }
        } else {
            if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
        }
    }

    window.trainAction = trainAction;
    window.singleStep = singleStep;
    window.resetSession = resetSession;
    fetchViz();
    drawChart(null);
})();
</script>";

