        (m_header("Hyperbolic Grokking", Some("Modular arithmetic a + b mod p on the Poincare disk")))

        // Stats
        div class="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-4" {
            @for (id, label) in [
                ("stat-status", "Status"), ("stat-step", "Step"),
